const SecurityVisualizer: React.FC<{ mode: string | null }> = ({ mode }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const particlesRef = useRef<any[]>([]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.parentElement?.clientWidth || 800;
        let h = canvas.parentElement?.clientHeight || 600;
        canvas.width = w;
        canvas.height = h;

        const cx = w / 2;
        const cy = h / 2;

        if (particlesRef.current.length === 0) {
            for (let i = 0; i < 150; i++) { // Reduced count
                particlesRef.current.push({
                    x: Math.random() * w,
                    y: Math.random() * h,
                    vx: (Math.random() - 0.5) * 0.5,
                    vy: (Math.random() - 0.5) * 0.5,
                    size: Math.random() * 2 + 1,
                    color: 'rgba(255, 255, 255, 0.2)',
                    aesChar: Math.random() > 0.5 ? '1' : '0'
                });
            }
        }

        let animationFrameId: number;

        const render = () => {
            // Simplified clear
            ctx.clearRect(0,0,w,h);
            ctx.fillStyle = 'rgba(5, 5, 5, 0.2)';
            ctx.fillRect(0, 0, w, h);

            const particles = particlesRef.current;

            particles.forEach((p, i) => {
                // Physics simplified...
                p.x += p.vx;
                p.y += p.vy;

                if (p.x < 0) p.x = w; if (p.x > w) p.x = 0;
                if (p.y < 0) p.y = h; if (p.y > h) p.y = 0;

                ctx.fillStyle = mode ? '#69B7B2' : 'rgba(255, 255, 255, 0.2)';
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI*2);
                ctx.fill();
            });

            // --- STATIC OVERLAYS based on Mode ---
            if (mode === 'airgap') {
                ctx.strokeStyle = '#ef4444';
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.arc(cx, cy, 250, 0, Math.PI*2); ctx.stroke();
            } 

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, [mode]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none mix-blend-screen opacity-80" />;
};

