import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let frameId: number;
        let time = 0;

        // 3D PARTICLE ENGINE
        const PARTICLE_COUNT = 800;
        const CAM_Z = 800;
        let CX = w * 0.5;
        let CY = h * 0.5;

        interface Point3D { x: number; y: number; z: number }

        // Particle State
        const particles = new Float32Array(PARTICLE_COUNT * 9); 
        // Layout: [curX, curY, curZ, tgtX, tgtY, tgtZ, colorIdx, size, randomOffset]
        // Storing basic types in TypedArray is faster for math, but we need colors.
        // We'll use a parallel array for colors to keep it simple or a color palette index.
        const colors = ['#8b5cf6', '#a78bfa', '#22d3ee', '#c4b5fd'];
        const particleColors = new Uint8Array(PARTICLE_COUNT);

        // Pre-allocate Sort Buffer to avoid GC
        // We store indices here and sort indices based on Z depth
        const renderOrder = new Int32Array(PARTICLE_COUNT);
        const depthBuffer = new Float32Array(PARTICLE_COUNT);

        let phase = 0; // 0: CLOUD, 1: SPHERE, 2: CUBE
        let phaseTimer = 0;
        const PHASE_DURATION = 400; 

        // Generators
        const setCloudTarget = (i: number) => {
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.random() * Math.PI * 2;
            const rMain = 250 + Math.random() * 50;
            const rTube = 80 + Math.random() * 40;

            const idx = i * 9;
            particles[idx + 3] = (rMain + rTube * Math.cos(phi)) * Math.cos(theta); // tx
            particles[idx + 4] = (rMain + rTube * Math.cos(phi)) * Math.sin(theta); // ty
            particles[idx + 5] = rTube * Math.sin(phi); // tz
        };

        const setSphereTarget = (i: number, total: number, radius: number) => {
            const phi = Math.acos(-1 + (2 * i) / total);
            const theta = Math.sqrt(total * Math.PI) * phi;

            const idx = i * 9;
            particles[idx + 3] = radius * Math.cos(theta) * Math.sin(phi);
            particles[idx + 4] = radius * Math.sin(theta) * Math.sin(phi);
            particles[idx + 5] = radius * Math.cos(phi);
        };

        const setCubeTarget = (i: number, total: number) => {
            const dim = Math.floor(Math.cbrt(total));
            const remainder = i % (dim*dim*dim);
            const x = (remainder % dim);
            const y = Math.floor((remainder / dim) % dim);
            const z = Math.floor(remainder / (dim * dim));
            const spacing = 40;
            const offset = (dim * spacing) / 2;

            const idx = i * 9;
            particles[idx + 3] = x * spacing - offset;
            particles[idx + 4] = y * spacing - offset;
            particles[idx + 5] = z * spacing - offset;
        };

        // Initialize
        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const idx = i * 9;
            setCloudTarget(i); // Set initial targets
            // Set current pos to target initially
            particles[idx] = particles[idx+3];
            particles[idx+1] = particles[idx+4];
            particles[idx+2] = particles[idx+5];

            particleColors[i] = Math.floor(Math.random() * colors.length);
            particles[idx+7] = Math.random() > 0.9 ? 2.5 : 1.2; // Size
            particles[idx+8] = Math.random() * Math.PI * 2; // Offset

            renderOrder[i] = i;
        }

        const setTargetShape = (shape: number) => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                if (shape === 0) setCloudTarget(i);
                else if (shape === 1) setSphereTarget(i, PARTICLE_COUNT, 220);
                else if (shape === 2) setCubeTarget(i, PARTICLE_COUNT);
            }
        };

        const render = () => {
            time += 0.008;
            phaseTimer++;

            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                setTargetShape(phase);
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const rotX = time * 0.3 + (mouseRef.current.y * 0.1);
            const rotY = time * 0.4 + (mouseRef.current.x * 0.1);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // 1. UPDATE & PROJECT
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * 9;

                // Lerp current to target
                particles[idx] += (particles[idx+3] - particles[idx]) * 0.04;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * 0.04;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * 0.04;

                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                // Add noise for Cloud phase
                if (phase === 0) {
                    const offset = particles[idx+8];
                    x += Math.sin(time * 2 + offset) * 2;
                    y += Math.cos(time * 3 + offset) * 2;
                }

                // Rotate
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                // Store projected Z for sorting
                depthBuffer[i] = z;

                // Store projected X/Y temporarily in target slots (optimization hack? No, let's keep array pure)
                // We'll recalculate projection during draw to save memory bandwidth vs storing a whole new array
                // Or just store the transformed X/Y/Z back into a buffer? 
                // Actually, let's just re-project. It's cheap.
                // We just need Z for sort.
            }

            // 2. SORT
            // Int32Array sort is fast in modern JS engines
            renderOrder.sort((a, b) => depthBuffer[b] - depthBuffer[a]);

            // 3. DRAW
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const pIdx = renderOrder[i];
                const z = depthBuffer[pIdx];
                const scale = CAM_Z / (CAM_Z + z);

                if (scale > 0) {
                    const idx = pIdx * 9;
                    // Re-calculate X/Y rotation (redundant but avoids allocation)
                    // Ideally we'd store this in a "renderBuffer"
                    let x = particles[idx];
                    let y = particles[idx+1];
                    let zRaw = particles[idx+2];

                    if (phase === 0) {
                        const offset = particles[idx+8];
                        x += Math.sin(time * 2 + offset) * 2;
                        y += Math.cos(time * 3 + offset) * 2;
                    }

                    let tx = x * cosY - zRaw * sinY;
                    let tz = zRaw * cosY + x * sinY;
                    x = tx; zRaw = tz;

                    let ty = y * cosX - zRaw * sinX;
                    y = ty;

                    const px = CX + x * scale;
                    const py = CY + y * scale;
                    const size = particles[idx+7] * scale;

                    ctx.fillStyle = colors[particleColors[pIdx]];
                    ctx.globalAlpha = Math.min(1, scale * 0.7);

                    // Optimization: Use rect for everything. At small sizes, rect ~ circle.
                    ctx.fillRect(px - size/2, py - size/2, size, size);
                }
            }
            ctx.globalAlpha = 1;

            // Connectivity lines (Optional visual flair - only for top 100 closest to save cycles)
            /*
            if (phase !== 0) {
                ctx.strokeStyle = phase === 2 ? 'rgba(34, 211, 238, 0.15)' : 'rgba(139, 92, 246, 0.1)';
                ctx.lineWidth = 0.5;
                // Only connect a subset
            }
            */

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
                CX = w * 0.5;
                CY = h * 0.5;
            }
        };
        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / w) * 2 - 1,
                y: ((e.clientY - rect.top) / h) * 2 - 1
            };
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full block" />;
};

import React, { useEffect, useRef } from 'react';

const ResourcesHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width;
        let h = canvas.height;

        let frame = 0;
        let frameId: number;

        // --- PERFORMANCE CONTROL ---
        let lastTime = 0;
        const TARGET_FPS = 60;
        const FRAME_INTERVAL = 1000 / TARGET_FPS;

        // State for dynamic events
        const extractions: { x: number, y: number, life: number, code: string, color: string }[] = [];
        const NODE_COLORS = ['#f59e0b', '#06b6d4', '#d946ef', '#ef4444', '#10b981', '#f43f5e'];

        const render = (timestamp: number) => {
            frameId = requestAnimationFrame(render);

            const deltaTime = timestamp - lastTime;
            if (deltaTime < FRAME_INTERVAL) return;
            lastTime = timestamp - (deltaTime % FRAME_INTERVAL);

            frame++;
            const time = frame * 0.015;
            const scroll = frame * 1.5;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            // 1. Draw "Strata" Lines (Optimized)
            const lines = 40; 
            const step = h / lines;
            const scanX = (time * 200) % (w + 400) - 200;

            ctx.lineWidth = 1.5;

            for (let i = 0; i < lines; i++) {
                const yBase = i * step + step/2;
                const hue = 150 + (1 - i/lines) * 60;

                // Pre-calculate style to avoid state change in loop? No, style changes per line.
                // Optimization: Don't create complex gradients every frame if possible.
                // For now, simpler stroke style is better for performance.

                ctx.beginPath();

                // Reduced resolution x+=15
                for (let x = 0; x <= w; x += 15) {
                    const worldX = x + scroll;
                    const worldZ = i * 50; 

                    // Simplified math
                    let elevation = Math.sin(worldX * 0.002 + worldZ * 0.001) * 30;

                    const distToScan = Math.abs(x - scanX);
                    if (distToScan < 100) {
                        const scanInfluence = 1 - distToScan / 100;
                        elevation += Math.sin(x * 0.2) * 5 * scanInfluence;
                    }

                    const perspectiveY = h * (0.2 + (i*i)/(lines*lines) * 0.8);
                    const finalY = perspectiveY + elevation;

                    if (x === 0) ctx.moveTo(x, finalY);
                    else ctx.lineTo(x, finalY);
                }

                // Only use expensive gradient for the active scan line
                if (scanX > -150 && scanX < w + 150) {
                    const grad = ctx.createLinearGradient(scanX - 100, 0, scanX + 100, 0);
                    grad.addColorStop(0, `hsla(${hue}, 50%, 40%, 0.1)`);
                    grad.addColorStop(0.5, `hsla(${hue}, 90%, 80%, 0.8)`);
                    grad.addColorStop(1, `hsla(${hue}, 50%, 40%, 0.1)`);
                    ctx.strokeStyle = grad;
                } else {
                    ctx.strokeStyle = `hsla(${hue}, 60%, 50%, 0.15)`;
                }
                ctx.stroke();
            }

            // 2. Draw Resources (Batched by type if possible, but they are sparse)
            const dotCount = 8;
            for(let j=0; j<dotCount; j++) {
                const nodeColor = NODE_COLORS[j % NODE_COLORS.length];
                const dx = (j * (w / dotCount) + (w/dotCount/2)) % w;
                const dy = (h * 0.35) + Math.sin(frame * 0.02 + j * 100) * (h * 0.35) + (h * 0.15);

                const distToScan = Math.abs(dx - scanX);

                // Logic: Extraction Trigger
                if (distToScan < 5 && Math.random() > 0.98) {
                    const tooClose = extractions.some(e => Math.abs(e.x - dx) < 20);
                    if (!tooClose) {
                        extractions.push({ 
                            x: dx, y: dy, life: 1.0, 
                            code: "RES-" + Math.floor(Math.random() * 99),
                            color: nodeColor
                        });
                    }
                }

                if (distToScan < 70) {
                    ctx.fillStyle = nodeColor;
                    const size = 6 * (1 + Math.sin(frame * 0.2) * 0.3);
                    ctx.fillRect(dx - size/2, dy - size/2, size, size);
                } else {
                    ctx.fillStyle = `rgba(255,255,255,0.1)`;
                    ctx.fillRect(dx - 1.5, dy - 1.5, 3, 3);
                }
            }

            // 3. Render Active Extractions
            // Batch the beams? They have different colors.
            // But we can batch the white packets.
            const packets: {x:number, y:number}[] = [];

            for (let i = extractions.length - 1; i >= 0; i--) {
                const ex = extractions[i];
                ex.life -= 0.015;
                ex.x -= 1.5;

                if (ex.life <= 0) {
                    extractions.splice(i, 1);
                    continue;
                }

                // Beam
                const beamHeight = 150 * (1 - ex.life);
                ctx.fillStyle = ex.color;
                ctx.globalAlpha = Math.sin(ex.life * Math.PI) * 0.6;
                ctx.fillRect(ex.x - 1, ex.y - beamHeight, 2, beamHeight);

                // Text
                if (ex.life > 0.4) {
                    ctx.font = '10px monospace';
                    ctx.fillText(`[${ex.code}]`, ex.x + 8, ex.y - beamHeight);
                }

                ctx.globalAlpha = 1;

                // Collect packet
                const travelProgress = Math.pow(1 - ex.life, 2); 
                const packetY = ex.y - (travelProgress * ex.y);
                packets.push({x: ex.x, y: packetY});
            }

            // Draw all packets in one pass
            if (packets.length > 0) {
                ctx.fillStyle = '#ffffff';
                ctx.beginPath();
                packets.forEach(p => {
                    ctx.rect(p.x - 2, p.y - 2, 4, 4);
                });
                ctx.fill();
            }
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                w = canvas.width = rect.width;
                h = canvas.height = rect.height;
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();

        frameId = requestAnimationFrame(render);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

export const ResourcesHeroVisualizer = React.memo(ResourcesHeroVisualizerComponent);

import React, { useEffect, useRef } from 'react';

const HeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas) return;

        // OPTIMIZATION: alpha: false eliminates the browser's need to composite 
        // the canvas against the DOM background.
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = canvas.width;
        let height = canvas.height;
        let cx = width / 2;
        let cy = height / 2;

        let frameId: number;
        let isVisible = true;

        // --- 3D ENGINE SETTINGS ---
        const FL = 800;
        let mouseX = 0;
        let mouseY = 0;
        let targetRotX = 0;
        let targetRotY = 0;

        // --- ANIMATION STATE ---
        let phase = 0; 
        let phaseTimer = 0;
        let globalTime = 0;
        let loopSeed = 0; 
        let meshOpacity = 0; 

        // --- GEOMETRY DATA STRUCTURES ---
        const SHEET_SIZE = 150; 

        // Pre-allocate objects to avoid Garbage Collection during render loop
        const createVec = (x: number, y: number, z: number) => ({ x, y, z });

        const flatVerts = [
            createVec(-SHEET_SIZE, -SHEET_SIZE * 1.4, 0), createVec(0, -SHEET_SIZE * 1.4, 0), createVec(SHEET_SIZE, -SHEET_SIZE * 1.4, 0),
            createVec(-SHEET_SIZE, 0, 0),                 createVec(0, 0, 0),                 createVec(SHEET_SIZE, 0, 0),
            createVec(-SHEET_SIZE, SHEET_SIZE * 1.4, 0),  createVec(0, SHEET_SIZE * 1.4, 0),  createVec(SHEET_SIZE, SHEET_SIZE * 1.4, 0)
        ];

        const planeVerts = [
            createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),
            createVec(-SHEET_SIZE * 1.2, SHEET_SIZE, 20), createVec(0, -SHEET_SIZE * 0.5, -50), createVec(SHEET_SIZE * 1.2, SHEET_SIZE, 20),
            createVec(-20, SHEET_SIZE * 1.4, 0),     createVec(0, SHEET_SIZE * 1.4, 0),      createVec(20, SHEET_SIZE * 1.4, 0)
        ];

        // Mutable state vectors
        const currentVerts = flatVerts.map(v => ({...v}));
        const worldVertsBuffer = flatVerts.map(() => ({ x: 0, y: 0, z: 0, px: 0, py: 0, scale: 0 }));

        const planePos = { x: 0, y: 0, z: 0 };
        const planeVel = { x: 0, y: 0, z: 0 };
        const planeRot = { x: 0, y: 0, z: 0 };

        // --- PARTICLES ---
        const MAX_PARTICLES = 60;
        const particles = Array.from({ length: MAX_PARTICLES }, () => ({
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            life: 0,
            color: '#fff',
            type: 'ember' as 'data' | 'trail' | 'ember',
            active: false
        }));

        const lerp = (start: number, end: number, t: number) => start + (end - start) * t;

        const spawnParticle = (type: 'data' | 'trail' | 'ember', ox: number, oy: number, oz: number, spread: number) => {
            // Find first inactive particle to reuse memory
            for (let i = 0; i < MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) {
                    p.active = true;
                    p.x = ox + (Math.random() - 0.5) * spread;
                    p.y = oy + (Math.random() - 0.5) * spread;
                    p.z = oz + (Math.random() - 0.5) * spread;
                    p.vx = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vy = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vz = type === 'trail' ? 10 : (Math.random() - 0.5) * 5;
                    p.life = 1.0;
                    p.color = type === 'data' ? '#69B7B2' : type === 'ember' ? '#f59e0b' : '#ffffff';
                    p.type = type;
                    break; 
                }
            }
        };

        const render = () => {
            frameId = requestAnimationFrame(render);
            if (!isVisible) return;

            globalTime += 0.016;

            // OPTIMIZATION: Single fillRect with low opacity creates the trail effect.
            // No need to clearRect + fillRect(black) + fillRect(opacity).
            // This is a 2x reduction in full-screen draw calls.
            ctx.fillStyle = 'rgba(2, 2, 2, 0.25)';
            ctx.fillRect(0, 0, width, height);

            // Camera Smoothing
            targetRotY += (mouseX * 0.5 - targetRotY) * 0.05;
            targetRotX += (mouseY * 0.5 - targetRotX) * 0.05;

            const cosY = Math.cos(targetRotX);
            const sinY = Math.sin(targetRotX);
            const cosX = Math.cos(targetRotY); 
            const sinX = Math.sin(targetRotY);

            // --- PHASE LOGIC ---
            if (phase === 0) { // COALESCE
                phaseTimer += 0.006;
                meshOpacity = Math.min(1, phaseTimer);
                const t = Math.min(1, phaseTimer / 2.0);
                const ease = 1 - Math.pow(1 - t, 4); 

                for(let i=0; i<9; i++) {
                    const float = Math.sin(globalTime * 2 + i) * 20 * (1-ease);
                    // Pre-calc noise factors to avoid repetitive Math calls
                    const idx = i * 1.0;
                    const noiseX = Math.sin(idx * 12.3 + loopSeed) * 1200 + float;
                    const noiseY = Math.cos(idx * 45.6 + loopSeed) * 800 + float;
                    const noiseZ = Math.sin(idx * 78.9 + loopSeed) * 1000 - 500;

                    const cv = currentVerts[i];
                    const fv = flatVerts[i];
                    cv.x = lerp(noiseX, fv.x, ease);
                    cv.y = lerp(noiseY, fv.y, ease);
                    cv.z = lerp(noiseZ, fv.z, ease);
                }

                if (Math.random() > 0.85 && phaseTimer < 1.5) spawnParticle('data', 0, 0, 0, 800);
                if (phaseTimer > 2.5) { phase = 1; phaseTimer = 0; meshOpacity = 1; }
            }
            else if (phase === 1) { // FOLD
                // Slower folding speed (reduced from 0.012 to 0.01)
                phaseTimer += 0.01;
                const t = Math.min(1, phaseTimer);
                const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

                for(let i=0; i<9; i++) {
                    currentVerts[i].x = lerp(flatVerts[i].x, planeVerts[i].x, ease);
                    currentVerts[i].y = lerp(flatVerts[i].y, planeVerts[i].y, ease);
                    currentVerts[i].z = lerp(flatVerts[i].z, planeVerts[i].z, ease);
                }

                if (t > 0.8) {
                    // Shake effect
                    cx = width/2 + (Math.random()-0.5)*5;
                    cy = height/2 + (Math.random()-0.5)*5;
                } else {
                    cx = width/2; cy = height/2;
                }

                if (phaseTimer > 1.2) { 
                    phase = 2; phaseTimer = 0;
                    // Reset vectors for flight
                    planePos.x = 0; planePos.y = 0; planePos.z = 0;
                    planeRot.x = 0; planeRot.y = 0; planeRot.z = 0;

                    const angle = (Math.random() - 0.5) * 2.5;
                    const lift = (Math.random() - 0.5) * 1.0;
                    planeVel.x = Math.sin(angle) * 8;
                    planeVel.y = Math.sin(lift) * 6;
                    planeVel.z = 18;
                }
            }
            else if (phase === 2) { // FLIGHT
                phaseTimer += 0.016;
                planeVel.z += 0.85;
                planePos.x += planeVel.x;
                planePos.y += planeVel.y;
                planePos.z += planeVel.z;

                // Banking logic
                const targetBank = planeVel.x * 0.03;
                planeRot.z += (targetBank - planeRot.z) * 0.1;
                const targetPitch = planeVel.y * 0.03;
                planeRot.x += (targetPitch - planeRot.x) * 0.1;
                planeRot.y += planeVel.x * 0.002;

                if (planePos.z > 2000) meshOpacity = Math.max(0, 1 - ((planePos.z - 2000) / 1500));

                if(Math.random() > 0.5) spawnParticle('ember', planePos.x, planePos.y, planePos.z, 10);
                if(Math.random() > 0.8) spawnParticle('trail', planePos.x, planePos.y, planePos.z, 20);

                if (planePos.z > 3500) { 
                    phase = 3; 
                    phaseTimer = 0; 
                }
            }
            else if (phase === 3) { // RESET
                loopSeed += 13.7;
                meshOpacity = 0;
                phase = 0;
                cx = width/2; cy = height/2;

                // CRITICAL FIX: Reset Plane Position for next loop
                planePos.x = 0; planePos.y = 0; planePos.z = 0;
                planeRot.x = 0; planeRot.y = 0; planeRot.z = 0;
                planeVel.x = 0; planeVel.y = 0; planeVel.z = 0;
            }

            // --- TRANSFORM & PROJECT (BATCHED) ---
            for(let i=0; i<9; i++) {
                const v = currentVerts[i];
                let x = v.x + planePos.x;
                let y = v.y + planePos.y;
                let z = v.z + planePos.z;

                if (phase === 2) {
                    // Apply Plane Rotation Matrix
                    const cosRY = Math.cos(planeRot.y); const sinRY = Math.sin(planeRot.y);
                    const cosRX = Math.cos(planeRot.x); const sinRX = Math.sin(planeRot.x);

                    let tx = x * cosRY - z * sinRY;
                    let tz = z * cosRY + x * sinRY;
                    x = tx; z = tz;
                    let ty = y * cosRX - z * sinRX;
                    let tz2 = z * cosRX + y * sinRX;
                    y = ty; z = tz2;
                }

                // Apply Camera Rotation Matrix
                let y1 = y * cosY - z * sinY;
                let z1 = z * cosY + y * sinY;
                let x1 = x * cosX - z1 * sinX;
                let z2 = z1 * cosX + x * sinX;

                const scale = FL / (FL + z2);
                const buff = worldVertsBuffer[i];
                buff.x = x1; buff.y = y1; buff.z = z2;
                buff.px = cx + x1 * scale;
                buff.py = cy + y1 * scale;
                buff.scale = scale;
            }

            // --- DRAW MESH (BATCHED) ---
            // Instead of drawing each triangle individually (which changes context state),
            // we batch "base" polygons and "accent" polygons to reduce draw calls.
            if (meshOpacity > 0.01) {
                const accentFill = phase === 2 ? `rgba(105,183,178,${meshOpacity * 0.2})` : `rgba(255,255,255,${meshOpacity * 0.1})`;
                const baseFill = `rgba(255,255,255,${meshOpacity * 0.05})`;

                ctx.lineWidth = 1;
                ctx.strokeStyle = `rgba(255,255,255,${0.1 * meshOpacity})`;

                // Helper to add path
                const addTri = (i1: number, i2: number, i3: number) => {
                    const p1 = worldVertsBuffer[i1];
                    const p2 = worldVertsBuffer[i2];
                    const p3 = worldVertsBuffer[i3];
                    // Culling check
                    if (p1.z < -FL+10 || p2.z < -FL+10 || p3.z < -FL+10) return;

                    ctx.moveTo(p1.px, p1.py);
                    ctx.lineTo(p2.px, p2.py);
                    ctx.lineTo(p3.px, p3.py);
                    ctx.lineTo(p1.px, p1.py);
                };

                // BATCH 1: Base Triangles
                ctx.beginPath();
                addTri(0, 1, 3);
                addTri(1, 2, 5);
                addTri(3, 4, 6);
                addTri(4, 5, 8);
                ctx.fillStyle = baseFill;
                ctx.fill();
                ctx.stroke();

                // BATCH 2: Accent Triangles
                ctx.beginPath();
                addTri(1, 4, 3);
                addTri(1, 4, 5);
                addTri(4, 7, 6);
                addTri(4, 7, 8);
                ctx.fillStyle = accentFill;
                ctx.fill();
                ctx.stroke();

                // Highlight Line
                const p1 = worldVertsBuffer[1]; const p4 = worldVertsBuffer[4]; const p7 = worldVertsBuffer[7];
                if(p1.z > -FL) {
                    ctx.beginPath();
                    ctx.strokeStyle = phase === 1 ? '#f59e0b' : '#69B7B2';
                    ctx.lineWidth = 2;
