import React, { useState, useEffect, useRef } from 'react';
import { Send, MapPin, Mail, Globe, CheckCircle2, ArrowRight, Radio, Building2, ChevronDown, CheckSquare } from 'lucide-react';

// --- NEW VISUALIZER: 3-STEP CONTACT ENGINE ---
const ContactHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;

        let frame = 0;
        const PARTICLE_COUNT = 180;
        const PHASE_LENGTH = 500; // Frames per phase

        interface Particle {
            x: number; y: number;
            tx: number; ty: number; // Target
            vx: number; vy: number;
            color: string;
            phaseOffset: number;
        }

        const particles: Particle[] = [];
        const colors = ['#69B7B2', '#f59e0b', '#ef4444']; // Teal, Amber, Red

        // Init Particles
        for(let i=0; i<PARTICLE_COUNT; i++) {
            particles.push({
                x: Math.random() * w,
                y: Math.random() * h,
                tx: Math.random() * w,
                ty: Math.random() * h,
                vx: 0, vy: 0,
                color: colors[i % 3],
                phaseOffset: Math.random() * Math.PI * 2
            });
        }

        let animationFrameId: number;

        const render = () => {
            frame++;
            const phase = Math.floor(frame / PHASE_LENGTH) % 3;
            const time = frame * 0.01;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const cx = w / 2;
            const cy = h / 2;

            // --- PHASE LOGIC: SET TARGETS ---
            if (frame % PHASE_LENGTH === 0) {
                particles.forEach((p, i) => {
                    if (phase === 0) {
                        // PHASE 1: BROADCAST (Signal Rings)
                        const ring = i % 5;
                        const angle = (i / PARTICLE_COUNT) * Math.PI * 2 + (ring * 0.5);
                        const radius = 50 + ring * 60 + (Math.random() * 20);
                        p.tx = cx + Math.cos(angle) * radius;
                        p.ty = cy + Math.sin(angle) * radius;
                    } else if (phase === 1) {
                        // PHASE 2: NETWORK (Global Map Approximation)
                        // Create an elliptical distribution
                        const angle = Math.random() * Math.PI * 2;
                        const r = Math.sqrt(Math.random()) * (Math.min(w,h) * 0.4);
                        p.tx = cx + Math.cos(angle) * r * 1.6; // Wider
                        p.ty = cy + Math.sin(angle) * r * 0.9;
                    } else {
                        // PHASE 3: HANDSHAKE (Structured Grid/Lattice)
                        const cols = 15;
                        const rows = 12;
                        const spacingX = w / cols;
                        const spacingY = h / rows;
                        const c = i % cols;
                        const r = Math.floor(i / cols);

                        // Honeycomb offset
                        const xOff = (r % 2) * (spacingX / 2);

                        p.tx = (c * spacingX) + xOff + spacingX/2;
                        p.ty = (r * spacingY) + spacingY/2;
                    }
                });
            }

            // --- DRAW & PHYSICS ---
            ctx.lineWidth = 1;

            // Connect nearby particles (O(N^2) optimized by distance check)
            ctx.beginPath();
            ctx.strokeStyle = phase === 0 ? '#69B7B2' : phase === 1 ? '#f59e0b' : '#ef4444';

            for(let i=0; i<PARTICLE_COUNT; i++) {
                const p = particles[i];

                // Move towards target
                p.x += (p.tx - p.x) * 0.04;
                p.y += (p.ty - p.y) * 0.04;

                // Add organic noise based on phase
                if (phase === 0) {
                    // Rotate rings
                    const oldX = p.x - cx;
                    const oldY = p.y - cy;
                    const rot = 0.002 * (i % 2 === 0 ? 1 : -1);
                    p.x = cx + (oldX * Math.cos(rot) - oldY * Math.sin(rot));
                    p.y = cy + (oldX * Math.sin(rot) + oldY * Math.cos(rot));
                } else if (phase === 1) {
                    // Jitter
                    p.x += Math.sin(time + p.phaseOffset) * 0.5;
                    p.y += Math.cos(time + p.phaseOffset) * 0.5;
                }

                // Draw Connections
                for (let j = i + 1; j < PARTICLE_COUNT; j++) {
                    const p2 = particles[j];
                    const dx = p.x - p2.x;
                    const dy = p.y - p2.y;
                    const distSq = dx*dx + dy*dy;

                    // Connection distance threshold
                    if (distSq < 6400) { // 80px
                        // Draw line
                        ctx.moveTo(p.x, p.y);
                        ctx.lineTo(p2.x, p2.y);
                    }
                }
            }

            // Stroke all connections at once
            ctx.globalAlpha = 0.15;
            ctx.stroke();

            // Draw Points
            ctx.globalAlpha = 0.8;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const p = particles[i];
                ctx.fillStyle = p.color;
                const size = phase === 2 ? 2.5 : 1.5;
                ctx.beginPath();
                ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.globalAlpha = 1;

            // HUD Elements
            ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            const label = phase === 0 ? "BROADCAST_SIGNAL" : phase === 1 ? "NETWORK_TRAVERSAL" : "SECURE_HANDSHAKE";
            ctx.fillText(`/// STATUS: ${label} ///`, cx, h - 40);

            // Progress Bar
            const progress = (frame % PHASE_LENGTH) / PHASE_LENGTH;
            ctx.fillStyle = '#333';
            ctx.fillRect(cx - 50, h - 30, 100, 2);
            ctx.fillStyle = '#69B7B2';
            ctx.fillRect(cx - 50, h - 30, 100 * progress, 2);

            animationFrameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="block w-full h-full opacity-60 mix-blend-screen" />;
};

