import React, { useEffect, useRef } from 'react';

export const ContactHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let frameId: number;
        let time = 0;

        // --- 3D ENGINE SETTINGS ---
        const PARTICLE_COUNT = 600;
        const CAM_Z = 700;
        const CX = w / 2;
        const CY = h / 2;

        // --- STATE ---
        const particles = new Float32Array(PARTICLE_COUNT * 7); // [x, y, z, tx, ty, tz, colorIdx]
        // Color Palette: Teal, Amber, White, Red (Alert)
        const colors = ['#69B7B2', '#f59e0b', '#ffffff', '#ef4444'];

        let phase = 0; // 0: SIGNAL, 1: HANDSHAKE, 2: LINK
        let phaseTimer = 0;
        const PHASE_DURATION = 500;

        // --- INITIALIZE ---
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * 7;
            // Start random
            particles[idx] = (Math.random() - 0.5) * 800;
            particles[idx+1] = (Math.random() - 0.5) * 800;
            particles[idx+2] = (Math.random() - 0.5) * 800;
            particles[idx+6] = Math.floor(Math.random() * 3); // 0-2 (Teal, Amber, White)
        }

        // --- SHAPE GENERATORS ---
        const setSignalTarget = (i: number) => {
            // Chaotic Cloud / Signal Noise
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            const r = 150 + Math.random() * 250;

            const idx = i * 7;
            particles[idx+3] = r * Math.sin(phi) * Math.cos(theta);
            particles[idx+4] = r * Math.sin(phi) * Math.sin(theta);
            particles[idx+5] = r * Math.cos(phi);
        };

        const setHandshakeTarget = (i: number) => {
            // Two Interlocking Rings (Gyroscope)
            const idx = i * 7;
            const ring = i % 3;
            const angle = (i / PARTICLE_COUNT) * Math.PI * 2 * 3; // multiple loops
            const r = 220;

            if (ring === 0) { // Horizontal
                particles[idx+3] = r * Math.cos(angle);
                particles[idx+4] = 0;
                particles[idx+5] = r * Math.sin(angle);
            } else if (ring === 1) { // Vertical
                particles[idx+3] = 0;
                particles[idx+4] = r * Math.cos(angle);
                particles[idx+5] = r * Math.sin(angle);
            } else { // Diagonal
                particles[idx+3] = r * Math.cos(angle) * 0.7;
                particles[idx+4] = r * Math.sin(angle) * 0.7;
                particles[idx+5] = r * Math.sin(angle);
            }
        };

        const setLinkTarget = (i: number) => {
            // Stable Sphere / Globe
            const idx = i * 7;
            const phi = Math.acos(-1 + (2 * i) / PARTICLE_COUNT);
            const theta = Math.sqrt(PARTICLE_COUNT * Math.PI) * phi;
            const r = 200;

            particles[idx+3] = r * Math.cos(theta) * Math.sin(phi);
            particles[idx+4] = r * Math.sin(theta) * Math.sin(phi);
            particles[idx+5] = r * Math.cos(phi);
        };

        const updateTargets = () => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                if (phase === 0) setSignalTarget(i);
                else if (phase === 1) setHandshakeTarget(i);
                else setLinkTarget(i);
            }
        };
        updateTargets(); // Init

        const render = () => {
            time += 0.01;
            phaseTimer++;

            // Cycle Phases
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            // Rotation Logic based on Phase
            const rotSpeed = phase === 0 ? 0.2 : 0.5;
            const rotY = time * rotSpeed;
            const rotX = time * 0.1;

            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            ctx.lineWidth = 1;

            // DRAW LOOP
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * 7;

                // Move towards target
                const easing = 0.03;
                particles[idx] += (particles[idx+3] - particles[idx]) * easing;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * easing;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * easing;

                // Noise in Signal Phase
                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                if (phase === 0) {
                    x += Math.sin(time * 5 + i) * 5;
                    y += Math.cos(time * 3 + i) * 5;
                }

                // 3D Rotation
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                // Projection
                const scale = CAM_Z / (CAM_Z + z);

                if (z > -CAM_Z + 10 && scale > 0) {
                    const px = CX + x * scale;
                    const py = CY + y * scale;
                    const size = scale * (phase === 0 ? 1.5 : 2);
                    const alpha = Math.min(1, scale * 0.8);

                    // Color logic
                    const colorIdx = particles[idx+6];
                    ctx.fillStyle = colors[colorIdx];
                    ctx.globalAlpha = alpha;

                    ctx.beginPath();
                    ctx.arc(px, py, size, 0, Math.PI * 2);
                    ctx.fill();

                    // Connect lines in Link Phase
                    if (phase === 2 && i % 10 === 0) {
                        // Just connect to center for "Globe" feel, simpler than spatial hashing
                        // Or connect to previous particle
                        const prevIdx = ((i - 1 + PARTICLE_COUNT) % PARTICLE_COUNT) * 7;
                        // We need the projected pos of prev particle. 
                        // To save cycles, we'll just draw lines for a subset without re-projecting prev
                        // Actually, skip lines for performance unless we cache projected.
                    }
                }
            }
            ctx.globalAlpha = 1;

            // HUD Text
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
            const label = phase === 0 ? "SEARCHING_FREQUENCY" : phase === 1 ? "HANDSHAKE_PROTOCOL" : "LINK_ESTABLISHED";
            ctx.fillText(`/// STATUS: ${label} ///`, CX, h - 50);

            // Progress Bar
            const progress = phaseTimer / PHASE_DURATION;
            ctx.fillStyle = '#333';
            ctx.fillRect(CX - 50, h - 40, 100, 2);
            ctx.fillStyle = '#69B7B2';
            ctx.fillRect(CX - 50, h - 40, 100 * progress, 2);

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
                // Update centers
                // CX/CY used in render loop will update automatically if we use block scope vars re-assigned
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="block w-full h-full opacity-60 mix-blend-screen" />;
};

