import React, { useEffect, useRef } from 'react';

export const ContactHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            const { innerWidth, innerHeight } = window;
            mouseRef.current = {
                x: (e.clientX - innerWidth / 2) / (innerWidth / 2),
                y: (e.clientY - innerHeight / 2) / (innerHeight / 2)
            };
        };
        window.addEventListener('mousemove', handleMouseMove);
        return () => window.removeEventListener('mousemove', handleMouseMove);
    }, []);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let frameId: number;
        let time = 0;

        // --- 3D ENGINE SETTINGS ---
        const PARTICLE_COUNT = 500;
        const CAM_Z = 900;
        const CX = w / 2;
        const CY = h / 2;

        // --- STATE ---
        // x, y, z (current pos)
        // tx, ty, tz (target pos)
        // vx, vy, vz (velocity)
        // color (0-3 index)
        const P_SIZE = 10; 
        const data = new Float32Array(PARTICLE_COUNT * P_SIZE);
        const colors = ['#69B7B2', '#f59e0b', '#ffffff', '#ef4444'];

        let phase = 0; // 0: SIGNAL, 1: HANDSHAKE, 2: LINK
        let phaseTimer = 0;
        const PHASE_DURATION = 600;

        // --- INITIALIZE ---
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_SIZE;
            data[idx] = (Math.random() - 0.5) * 1000;
            data[idx+1] = (Math.random() - 0.5) * 1000;
            data[idx+2] = (Math.random() - 0.5) * 1000;
            data[idx+9] = Math.floor(Math.random() * 3); // Color
        }

        // --- SHAPE GENERATORS ---
        const setSignalTarget = (i: number) => {
            // Expanding Sphere / Explosion
            const idx = i * P_SIZE;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            const r = 300 + Math.random() * 100; // Large radius

            data[idx+3] = r * Math.sin(phi) * Math.cos(theta);
            data[idx+4] = r * Math.sin(phi) * Math.sin(theta);
            data[idx+5] = r * Math.cos(phi);
        };

        const setHandshakeTarget = (i: number) => {
            // Dual Orbiting Rings
            const idx = i * P_SIZE;
            const isRingA = i % 2 === 0;
            const angle = (i / PARTICLE_COUNT) * Math.PI * 8; // Multiple loops
            const r = 250;

            if (isRingA) {
                // Horizontal-ish
                data[idx+3] = r * Math.cos(angle);
                data[idx+4] = Math.sin(angle * 3) * 50; // Wobbly
                data[idx+5] = r * Math.sin(angle);
            } else {
                // Vertical-ish
                data[idx+3] = Math.sin(angle * 3) * 50;
                data[idx+4] = r * Math.cos(angle);
                data[idx+5] = r * Math.sin(angle);
            }
        };

        const setLinkTarget = (i: number) => {
            // Fibonacci Sphere (Even distribution)
            const idx = i * P_SIZE;
            const phi = Math.acos(1 - 2 * (i + 0.5) / PARTICLE_COUNT);
            const theta = Math.PI * (1 + Math.sqrt(5)) * (i + 0.5);
            const r = 220;

            data[idx+3] = r * Math.sin(phi) * Math.cos(theta);
            data[idx+4] = r * Math.sin(phi) * Math.sin(theta);
            data[idx+5] = r * Math.cos(phi);
        };

        const updateTargets = () => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                if (phase === 0) setSignalTarget(i);
                else if (phase === 1) setHandshakeTarget(i);
                else setLinkTarget(i);
            }
        };
        updateTargets(); // Init

        const render = () => {
            time += 0.01;
            phaseTimer++;

            // Cycle Phases
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            // Interaction Rotation
            const targetRotX = mouseRef.current.y * 0.5;
            const targetRotY = mouseRef.current.x * 0.5;

            // Auto Rotation
            const autoRotY = time * 0.2;

            const totalRotX = targetRotX;
            const totalRotY = targetRotY + autoRotY;

            const cosY = Math.cos(totalRotY), sinY = Math.sin(totalRotY);
            const cosX = Math.cos(totalRotX), sinX = Math.sin(totalRotX);

            // SPRING PHYSICS CONSTANTS
            const SPRING = 0.05;
            const DAMPING = 0.85;

            // Arrays for connectivity
            const projected: {x: number, y: number, z: number, idx: number}[] = [];

            // UPDATE LOOP
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_SIZE;

                // Physics: Spring to Target
                const ax = (data[idx+3] - data[idx]) * SPRING;
                const ay = (data[idx+4] - data[idx+1]) * SPRING;
                const az = (data[idx+5] - data[idx+2]) * SPRING;

                data[idx+6] += ax;
                data[idx+7] += ay;
                data[idx+8] += az;

                data[idx+6] *= DAMPING;
                data[idx+7] *= DAMPING;
                data[idx+8] *= DAMPING;

                data[idx] += data[idx+6];
                data[idx+1] += data[idx+7];
                data[idx+2] += data[idx+8];

                // Noise for Signal Phase
                let x = data[idx];
                let y = data[idx+1];
                let z = data[idx+2];

                if (phase === 0) {
                    x += Math.sin(time * 10 + i) * 5;
                    y += Math.cos(time * 8 + i) * 5;
                    z += Math.sin(time * 5 + i) * 5;
                }

                // 3D Rotation
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                // Projection
                const scale = CAM_Z / (CAM_Z + z);

                if (z > -CAM_Z + 50 && scale > 0) {
                    const px = CX + x * scale;
                    const py = CY + y * scale;

                    projected.push({x: px, y: py, z: z, idx});
                }
            }

            // RENDER LOOP
            // Sort by Z for proper layering (painter's algorithm)
            projected.sort((a, b) => b.z - a.z);

            ctx.lineWidth = 1;

            for(let i=0; i<projected.length; i++) {
                const p = projected[i];
                const scale = CAM_Z / (CAM_Z + p.z);
                const alpha = Math.min(1, scale * 0.8);
                const colorIdx = data[p.idx+9];

                // Draw Connections (Distance based, O(N) optimized by sorting or limiting check)
                // Only connect in Network phase or Handshake
                if (phase === 2 || phase === 1) {
                    // Check next few particles in sorted array (fast approximation)
                    for (let j = 1; j < 6; j++) {
                        if (i + j < projected.length) {
                            const p2 = projected[i+j];
                            const dx = p.x - p2.x;
                            const dy = p.y - p2.y;
                            const distSq = dx*dx + dy*dy;

                            // Distance threshold based on scale
                            if (distSq < 2500 * scale) {
                                ctx.strokeStyle = `rgba(105, 183, 178, ${0.15 * alpha})`;
                                ctx.beginPath();
                                ctx.moveTo(p.x, p.y);
                                ctx.lineTo(p2.x, p2.y);
                                ctx.stroke();
                            }
                        }
                    }
                }

                // Draw Particle
                ctx.fillStyle = colors[colorIdx];
                ctx.globalAlpha = alpha;
                const size = phase === 0 ? 1.5 * scale : 2 * scale;

                ctx.beginPath();
                ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
                ctx.fill();

                // Glow effect for active phase
                if (phase === 0 && Math.random() > 0.98) {
                    ctx.shadowBlur = 10;
                    ctx.shadowColor = '#fff';
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }
            }

            ctx.globalAlpha = 1;

            // HUD
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
            const label = phase === 0 ? "BROADCAST_SIGNAL" : phase === 1 ? "HANDSHAKE_PROTOCOL" : "SECURE_LINK";

            // Glitch effect on text
            const glitchX = Math.random() > 0.9 ? (Math.random() - 0.5) * 4 : 0;
            ctx.fillText(`/// STATUS: ${label} ///`, CX + glitchX, h - 50);

            // Progress Bar
            const progress = phaseTimer / PHASE_DURATION;
            ctx.fillStyle = 'rgba(255,255,255,0.1)';
            ctx.fillRect(CX - 50, h - 40, 100, 2);
            ctx.fillStyle = '#69B7B2';
            ctx.fillRect(CX - 50, h - 40, 100 * progress, 2);

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
                // Don't reset state, just center
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="block w-full h-full opacity-70 mix-blend-screen" />;
};

