              >
                {label}
                {(data.children || data.items) && <ChevronDown size={12} className={`transition-transform duration-300 ${activeDropdown === label ? 'rotate-180' : ''}`} />}
              </button>

              {/* MEGA MENU DROPDOWN (If items exist) */}
