import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let frameId: number;
        let time = 0;

        // 3D PARTICLE ENGINE
        const PARTICLE_COUNT = 800;
        const CAM_Z = 800;
        let CX = w * 0.5;
        let CY = h * 0.5;

        // Particle State
        const particles = new Float32Array(PARTICLE_COUNT * 9); 
        const colors = ['#8b5cf6', '#a78bfa', '#22d3ee', '#c4b5fd'];
        const particleColors = new Uint8Array(PARTICLE_COUNT);

        const renderOrder = new Int32Array(PARTICLE_COUNT);
        const depthBuffer = new Float32Array(PARTICLE_COUNT);

        let phase = 0; // 0: CLOUD, 1: SPHERE, 2: CUBE
        let phaseTimer = 0;
        const PHASE_DURATION = 400; 

        // Generators
        const setCloudTarget = (i: number) => {
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.random() * Math.PI * 2;
            const rMain = 250 + Math.random() * 50;
            const rTube = 80 + Math.random() * 40;

            const idx = i * 9;
            particles[idx + 3] = (rMain + rTube * Math.cos(phi)) * Math.cos(theta); // tx
            particles[idx + 4] = (rMain + rTube * Math.cos(phi)) * Math.sin(theta); // ty
            particles[idx + 5] = rTube * Math.sin(phi); // tz
        };

        const setSphereTarget = (i: number, total: number, radius: number) => {
            const phi = Math.acos(-1 + (2 * i) / total);
            const theta = Math.sqrt(total * Math.PI) * phi;

            const idx = i * 9;
            particles[idx + 3] = radius * Math.cos(theta) * Math.sin(phi);
            particles[idx + 4] = radius * Math.sin(theta) * Math.sin(phi);
            particles[idx + 5] = radius * Math.cos(phi);
        };

        const setCubeTarget = (i: number, total: number) => {
            const dim = Math.floor(Math.cbrt(total));
            const remainder = i % (dim*dim*dim);
            const x = (remainder % dim);
            const y = Math.floor((remainder / dim) % dim);
            const z = Math.floor(remainder / (dim * dim));
            const spacing = 40;
            const offset = (dim * spacing) / 2;

            const idx = i * 9;
            particles[idx + 3] = x * spacing - offset;
            particles[idx + 4] = y * spacing - offset;
            particles[idx + 5] = z * spacing - offset;
        };

        // Initialize
        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const idx = i * 9;
            setCloudTarget(i); 
            particles[idx] = particles[idx+3];
            particles[idx+1] = particles[idx+4];
            particles[idx+2] = particles[idx+5];

            particleColors[i] = Math.floor(Math.random() * colors.length);
            particles[idx+7] = Math.random() > 0.9 ? 2.5 : 1.2; // Size
            particles[idx+8] = Math.random() * Math.PI * 2; // Offset

            renderOrder[i] = i;
        }

        const setTargetShape = (shape: number) => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                if (shape === 0) setCloudTarget(i);
                else if (shape === 1) setSphereTarget(i, PARTICLE_COUNT, 220);
                else if (shape === 2) setCubeTarget(i, PARTICLE_COUNT);
            }
        };

        const render = () => {
            time += 0.007; // SLOWED from 0.008
            phaseTimer++;

            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                setTargetShape(phase);
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const rotX = time * 0.3 + (mouseRef.current.y * 0.1);
            const rotY = time * 0.4 + (mouseRef.current.x * 0.1);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // 1. UPDATE & PROJECT
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * 9;

                // Lerp current to target
                particles[idx] += (particles[idx+3] - particles[idx]) * 0.04;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * 0.04;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * 0.04;

                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                // Add noise for Cloud phase
                if (phase === 0) {
                    const offset = particles[idx+8];
                    x += Math.sin(time * 2 + offset) * 2;
                    y += Math.cos(time * 3 + offset) * 2;
                }

                // Rotate
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                // Store projected Z for sorting
                depthBuffer[i] = z;
            }

            // 2. SORT
            renderOrder.sort((a, b) => depthBuffer[b] - depthBuffer[a]);

            // 3. DRAW
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const pIdx = renderOrder[i];
                const z = depthBuffer[pIdx];
                const scale = CAM_Z / (CAM_Z + z);

                if (scale > 0) {
                    const idx = pIdx * 9;
                    let x = particles[idx];
                    let y = particles[idx+1];
                    let zRaw = particles[idx+2];

                    if (phase === 0) {
                        const offset = particles[idx+8];
                        x += Math.sin(time * 2 + offset) * 2;
                        y += Math.cos(time * 3 + offset) * 2;
                    }

                    let tx = x * cosY - zRaw * sinY;
                    let tz = zRaw * cosY + x * sinY;
                    x = tx; zRaw = tz;

                    let ty = y * cosX - zRaw * sinX;
                    y = ty;

                    const px = CX + x * scale;
                    const py = CY + y * scale;
                    const size = particles[idx+7] * scale;

                    ctx.fillStyle = colors[particleColors[pIdx]];
                    ctx.globalAlpha = Math.min(1, scale * 0.7);

                    ctx.fillRect(px - size/2, py - size/2, size, size);
                }
            }
            ctx.globalAlpha = 1;

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
                CX = w * 0.5;
                CY = h * 0.5;
            }
        };
        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / w) * 2 - 1,
                y: ((e.clientY - rect.top) / h) * 2 - 1
            };
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full block" />;
};

import React, { useEffect, useRef } from 'react';

const LogisticsHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.parentElement?.clientWidth || window.innerWidth;
        let h = canvas.parentElement?.clientHeight || window.innerHeight;
        let frame = 0;
        let frameId: number;

        const PHASE_DURATION = 900; 

        // --- 1. INDUCTION (Packages) ---
        interface PackageBox { x: number, y: number, w: number, h: number, speed: number, type: 'standard' | 'priority' | 'hazardous' }
        const packages: PackageBox[] = [];
        for(let i=0; i<100; i++) {
            packages.push({
                x: Math.random() * w * 1.5,
                y: Math.random() * h,
                w: 20 + Math.random() * 30,
                h: 10 + Math.random() * 20,
                speed: 1.8 + Math.random() * 2.7, // SLOWED from 2 + ... * 3
                type: Math.random() > 0.9 ? 'hazardous' : Math.random() > 0.8 ? 'priority' : 'standard'
            });
        }

        // --- 2. NETWORK (Globe) ---
        interface GlobePoint { x: number, y: number, z: number, r: number }
        const globePoints: GlobePoint[] = [];
        const count = 600;
        const r = 250;
        const phi = Math.PI * (3 - Math.sqrt(5));
        for(let i=0; i<count; i++) {
            const y = 1 - (i / (count - 1)) * 2;
            const radius = Math.sqrt(1 - y * y);
            const theta = phi * i;
            const x = Math.cos(theta) * radius;
            const z = Math.sin(theta) * radius;
            globePoints.push({ x: x*r, y: y*r, z: z*r, r: Math.random() > 0.95 ? 3 : 1.5 });
        }

        // --- 3. SORTATION (Radial) ---
        interface SortParticle { r: number, angle: number, speed: number, color: string }
        const sortParticles: SortParticle[] = [];
        for(let i=0; i<150; i++) {
            sortParticles.push({
                r: Math.random() * 50,
                angle: Math.random() * Math.PI * 2,
                speed: 1.8 + Math.random() * 3.6, // SLOWED
                color: Math.random() > 0.5 ? '#10b981' : '#f59e0b'
            });
        }

        const render = () => {
            frame++;
            const cycle = frame % (PHASE_DURATION * 3);
            let activePhase = 0;

            if (cycle < PHASE_DURATION) activePhase = 0;
            else if (cycle < PHASE_DURATION * 2) activePhase = 1;
            else activePhase = 2;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            if (activePhase === 0) {
                // --- INDUCTION BATCHED ---
                packages.forEach(p => {
                    p.x -= p.speed;
                    if (p.x < -100) { p.x = w + Math.random() * 200; p.y = Math.random() * h; }
                });

                // Batch 1: Standard (Cyan)
                ctx.fillStyle = '#06b6d4';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'standard') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // Batch 2: Priority (Amber)
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'priority') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // Batch 3: Hazardous (Red)
                ctx.fillStyle = '#ef4444';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'hazardous') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // 3D Sides (Batch)
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.beginPath();
                for (const p of packages) {
                    ctx.moveTo(p.x, p.y); 
                    ctx.lineTo(p.x+10, p.y-10); 
                    ctx.lineTo(p.x+p.w+10, p.y-10); 
                    ctx.lineTo(p.x+p.w, p.y);
                }
                ctx.fill();

            } else if (activePhase === 1) {
                // --- GLOBE BATCHED ---
                ctx.save();
                ctx.translate(w * 0.75, h * 0.5);
                const time = frame * 0.0045; // SLOWED from 0.005
                const cosT = Math.cos(time);
                const sinT = Math.sin(time);

                const bluePoints: number[] = []; 
                const amberPoints: number[] = []; 

                for (let i = 0; i < globePoints.length; i++) {
                    const p = globePoints[i];
                    let x = p.x * cosT - p.z * sinT;
                    let z = p.z * cosT + p.x * sinT;

                    if (z > -200) {
                        const scale = 500 / (500 + z);
                        const size = p.r * scale;
                        const px = x * scale;
                        const py = p.y * scale;

                        if (p.r > 2) {
                            amberPoints.push(px, py, size);
                        } else {
                            bluePoints.push(px, py, size);
                        }
                    }
                }

                // Draw Blue
                ctx.fillStyle = '#06b6d4';
                ctx.beginPath();
                for(let i=0; i<bluePoints.length; i+=3) {
                    ctx.rect(bluePoints[i], bluePoints[i+1], bluePoints[i+2], bluePoints[i+2]);
                }
                ctx.fill();

                // Draw Amber
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for(let i=0; i<amberPoints.length; i+=3) {
                    ctx.rect(amberPoints[i], amberPoints[i+1], amberPoints[i+2], amberPoints[i+2]);
                }
                ctx.fill();

                ctx.restore();

            } else {
                // --- SORTATION BATCHED ---
                ctx.save();
                ctx.translate(w * 0.75, h * 0.5);

                const greenParticles: number[] = [];
                const amberParticles: number[] = [];

                for (let i = 0; i < sortParticles.length; i++) {
                    const p = sortParticles[i];
                    p.r += p.speed;
                    p.angle += 0.045; // SLOWED from 0.05
                    if (p.r > 300) { p.r = 60; p.angle = Math.random() * Math.PI * 2; }

                    const px = Math.cos(p.angle) * p.r;
                    const py = Math.sin(p.angle) * p.r;

                    if (p.color === '#10b981') greenParticles.push(px, py);
                    else amberParticles.push(px, py);
                }

                // Draw Green
                ctx.fillStyle = '#10b981';
                ctx.beginPath();
                for(let i=0; i<greenParticles.length; i+=2) {
                    ctx.rect(greenParticles[i], greenParticles[i+1], 3, 3);
                }
                ctx.fill();

                // Draw Amber
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for(let i=0; i<amberParticles.length; i+=2) {
                    ctx.rect(amberParticles[i], amberParticles[i+1], 3, 3);
                }
                ctx.fill();

                ctx.restore();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

export const LogisticsHeroVisualizer = React.memo(LogisticsHeroVisualizerComponent);

import React, { useEffect, useRef } from 'react';

const IndustrialsHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width;
        let h = canvas.height;
        let time = 0;
        let frameId: number;

        // --- PERFORMANCE CONTROL ---
        let lastTime = 0;
        const TARGET_FPS = 60;
        const FRAME_INTERVAL = 1000 / TARGET_FPS;

        const CAM_Z = 600;
        let CX = w * 0.65;
        let CY = h * 0.5;
        const MODEL_SCALE = 1.4;

        interface Point { x: number, y: number, z: number }
        // Pre-calculate geometry once
        const parts: { points: Point[], rotationSpeed: number, color: string, type: 'casing' | 'rotor' }[] = [];

        // 1. CASING (Static Geometry)
        const casingPoints: Point[] = [];
        for (let z = -250; z <= 250; z += 40) {
            const r = (130 + Math.sin(z * 0.008) * 15) * MODEL_SCALE;
            for (let a = 0; a < Math.PI * 2; a += 0.3) {
                casingPoints.push({ x: Math.cos(a) * r, y: Math.sin(a) * r, z: z });
            }
        }
        parts.push({ points: casingPoints, rotationSpeed: 0.001, color: 'rgba(255, 255, 255, 0.15)', type: 'casing' });

        // 2. ROTORS (Dynamic Geometry)
        for (let i = 0; i < 6; i++) {
            const z = -200 + i * 80;
            const pts: Point[] = [];
            const rOuter = 115 * MODEL_SCALE;
            const bladeCount = 8 + (i%2)*4; 

            for (let b = 0; b < bladeCount; b++) {
                const angle = (Math.PI * 2 / bladeCount) * b;
                pts.push({ x: Math.cos(angle) * 40 * MODEL_SCALE, y: Math.sin(angle) * 40 * MODEL_SCALE, z });
                pts.push({ x: Math.cos(angle + 0.3) * rOuter, y: Math.sin(angle + 0.3) * rOuter, z });
            }
            parts.push({ points: pts, rotationSpeed: 0.13 * (i%2===0?1:-1), color: 'rgba(245, 158, 11, 0.8)', type: 'rotor' }); // SLOWED from 0.15
        }

        const render = (timestamp: number) => {
            frameId = requestAnimationFrame(render);

            const deltaTime = timestamp - lastTime;
            if (deltaTime < FRAME_INTERVAL) return;
            lastTime = timestamp - (deltaTime % FRAME_INTERVAL);

            time += 0.009; // SLOWED from 0.01

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const camRotY = time * 0.2;
            const camRotX = Math.sin(time * 0.25) * 0.15;

            const cosCY = Math.cos(camRotY), sinCY = Math.sin(camRotY);
            const cosCX = Math.cos(camRotX), sinCX = Math.sin(camRotX);

            for(let j=0; j<parts.length; j++) {
                const part = parts[j];
                const currentRot = time * part.rotationSpeed * 50;
                const cosR = Math.cos(currentRot);
                const sinR = Math.sin(currentRot);

                ctx.beginPath();
                ctx.strokeStyle = part.color;
                ctx.fillStyle = part.color;

                const pts = part.points;
                const len = pts.length;

                for (let i = 0; i < len; i++) {
                    const p = pts[i];
                    let x = p.x, y = p.y, z = p.z;

                    if (part.type === 'rotor') {
                        const nx = x * cosR - y * sinR;
                        const ny = x * sinR + y * cosR;
                        x = nx; y = ny;
                    }

                    const tx = x * cosCY - z * sinCY;
                    const tz = z * cosCY + x * sinCY;
                    x = tx; z = tz;

                    const ty = y * cosCX - z * sinCX;
                    const tz2 = z * cosCX + y * sinCX;
                    y = ty; z = tz2;

                    const scale = CAM_Z / (CAM_Z + z);

                    if (scale > 0) {
                        const px = CX + x * scale;
                        const py = CY + y * scale;

                        if (part.type === 'rotor') {
                            if (i % 2 === 0) ctx.moveTo(px, py); 
                            else ctx.lineTo(px, py);
                        } else {
                            ctx.rect(px, py, 1.5 * scale, 1.5 * scale);
                        }
                    }
                }

                if (part.type === 'rotor') {
                    ctx.stroke();
                } else {
                    ctx.fill();
                }
            }
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                w = canvas.width = rect.width;
                h = canvas.height = rect.height;
                CX = w * 0.65;
                CY = h * 0.5;
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        frameId = requestAnimationFrame(render);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

