import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE INIT ---
        const w = 400;
        const h = 400;

        // SEARCH
        const searchNodes = Array.from({ length: 40 }, () => ({
            r: Math.random() * 150,
            theta: Math.random() * Math.PI * 2,
            phi: Math.random() * Math.PI,
            speed: (Math.random() - 0.5) * 0.013 // SLOWED from 0.02
        }));

        // REDACTION (Document Scanner)
        const redactBlocks: {x: number, y: number, w: number, h: number, redacted: boolean}[] = [];
        const rRows = 12;
        const rCols = 6;
        for(let r=0; r<rRows; r++) {
            for(let c=0; c<rCols; c++) {
                if(Math.random() > 0.3) { // Random gaps
                    redactBlocks.push({
                        x: 40 + c * ((w-80)/rCols) + (Math.random() * 10),
                        y: 40 + r * ((h-80)/rRows),
                        w: ((w-80)/rCols) - 15,
                        h: 12,
                        redacted: false
                    });
                }
            }
        }

        // LOGIC (Directed Graph Flow)
        const logicNodes = [
            { x: w * 0.2, y: h * 0.5, id: 0 }, // Start
            { x: w * 0.5, y: h * 0.2, id: 1 }, // Top
            { x: w * 0.5, y: h * 0.8, id: 2 }, // Bottom
            { x: w * 0.8, y: h * 0.5, id: 3 }  // End
        ];
        const logicPaths = [
            { from: 0, to: 1 }, { from: 0, to: 2 }, 
            { from: 1, to: 3 }, { from: 2, to: 3 },
            { from: 1, to: 2 } // Cross chatter
        ];
        const logicPackets: { from: number, to: number, progress: number, speed: number }[] = [];

        // CORE (Reactor) - SPEED UNCHANGED
        const coreRings = [0.2, 0.4, 0.6, 0.8];

        // SHIELD (Hex)
        const shieldHexes: {x:number, y:number, active: number}[] = [];
        const hexSize = 20;
        for(let r=0; r<6; r++) {
            const count = 6 * r || 1;
            for(let i=0; i<count; i++) {
                const angle = (Math.PI*2/count)*i;
                const dist = r * hexSize * 1.8;
                shieldHexes.push({
                    x: Math.cos(angle) * dist,
                    y: Math.sin(angle) * dist,
                    active: 0
                });
            }
        }

        // SWARM (Tactical Pings)
        const swarmPings: {x: number, y: number, life: number, maxR: number}[] = [];

        // PREDICTIVE (Cone of Uncertainty)
        const predPaths = Array.from({length: 5}, (_, i) => ({
            offset: (i - 2) * 0.25, // spread
            phase: Math.random() * Math.PI * 2
        }));

        // TRANSLATION (Matrix to Grid)
        const transParticles = Array.from({length: 60}, () => ({
            x: Math.random() * w,
            y: Math.random() * h,
            speed: (2 + Math.random() * 3) * 0.67, // SLOWED
            char: String.fromCharCode(0x30A0 + Math.random() * 96) // Katakana
        }));

        // IDENTITY (Spiral)
        const identPoints = Array.from({length: 120}, (_, i) => ({
            angle: i * 0.15,
            dist: i * 1.2,
            pulse: Math.random() * Math.PI
        }));

        const render = () => {
            time += 0.0067; // SLOWED from 0.01 (Global Base Speed)

            // Fade clear
            ctx.fillStyle = 'rgba(5, 5, 5, 0.2)'; 
            ctx.fillRect(0, 0, w, h);

            const cx = w / 2;
            const cy = h / 2;

            if (mode === 'search') {
                ctx.translate(cx, cy);
                ctx.rotate(time * 0.1);

                searchNodes.forEach(n => {
                    n.theta += n.speed;
                    // Project 3D sphere to 2D
                    const x = n.r * Math.sin(n.phi) * Math.cos(n.theta);
                    const y = n.r * Math.sin(n.phi) * Math.sin(n.theta);
                    const z = n.r * Math.cos(n.phi);

                    const scale = 200 / (200 + z);
                    const alpha = (z + 150) / 300;

                    if (scale > 0) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
                        ctx.beginPath();
                        ctx.arc(x * scale, y * scale, 2 * scale, 0, Math.PI*2);
                        ctx.fill();

                        // Connect close nodes (expensive but looks cool)
                        if (Math.random() > 0.99) {
                            ctx.strokeStyle = color;
                            ctx.lineWidth = 0.5;
                            ctx.beginPath();
                            ctx.moveTo(x*scale, y*scale);
                            ctx.lineTo(0,0); // Connect to core
                            ctx.stroke();
                        }
                    }
                });
                ctx.globalAlpha = 1;
                ctx.setTransform(1,0,0,1,0,0); // Reset
            }

            else if (mode === 'redaction') {
                const scanSpeed = 100; // SLOWED from 150
                const scanY = (time * scanSpeed) % (h + 100) - 50;

                // Draw Blocks
                redactBlocks.forEach(b => {
                    // Logic: If scanline passes block, it becomes "redacted" (solid color)
                    // If scanline wraps around (is near top), reset
                    if (scanY < 0) b.redacted = false;

                    if (scanY > b.y && !b.redacted) {
                        b.redacted = true;
                    }

                    if (b.redacted) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 0.8;
                        ctx.fillRect(b.x, b.y, b.w, b.h);
                    } else {
                        // Unredacted "Text" look
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
                        ctx.fillRect(b.x, b.y, b.w, b.h);

                        // Highlight if being scanned
                        if (Math.abs(scanY - b.y) < 20) {
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(b.x, b.y, b.w, b.h);
                        }
                    }
                });
                ctx.globalAlpha = 1;

                // Draw Scanner Bar
                ctx.shadowBlur = 15;
                ctx.shadowColor = color;
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);

                // Scanner Light Cone
                const g = ctx.createLinearGradient(0, scanY, 0, scanY - 40);
                g.addColorStop(0, color); // solid color at bar
                g.addColorStop(1, 'transparent');
                ctx.fillStyle = g;
                ctx.fillRect(0, scanY - 40, w, 40);

                ctx.shadowBlur = 0;
            }

            else if (mode === 'logic') {
                // Spawn packets randomly (Slower rate)
                if (Math.random() > 0.94) { // Was 0.92
                    const path = logicPaths[Math.floor(Math.random() * logicPaths.length)];
                    logicPackets.push({ from: path.from, to: path.to, progress: 0, speed: (0.01 + Math.random()*0.02) * 0.67 }); // SLOWED
                }

                // Draw Paths
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                logicPaths.forEach(p => {
                    const start = logicNodes[p.from];
                    const end = logicNodes[p.to];
                    ctx.moveTo(start.x, start.y);
                    ctx.lineTo(end.x, end.y);
                });
                ctx.stroke();

                // Process & Draw Packets
                for (let i = logicPackets.length - 1; i >= 0; i--) {
                    const p = logicPackets[i];
                    p.progress += p.speed;

                    if (p.progress >= 1) {
                        // Pulse destination node
                        const endNode = logicNodes[p.to];
                        ctx.fillStyle = '#fff';
                        ctx.beginPath(); ctx.arc(endNode.x, endNode.y, 8, 0, Math.PI*2); ctx.fill();
                        logicPackets.splice(i, 1);
                        continue;
                    }

                    const start = logicNodes[p.from];
                    const end = logicNodes[p.to];
                    const x = start.x + (end.x - start.x) * p.progress;
                    const y = start.y + (end.y - start.y) * p.progress;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 5;
                    ctx.shadowColor = color;
                    ctx.beginPath();
                    ctx.arc(x, y, 4, 0, Math.PI*2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }

                // Draw Nodes
                logicNodes.forEach(n => {
                    ctx.fillStyle = '#1a1a1a';
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(n.x, n.y - 15);
                    ctx.lineTo(n.x + 15, n.y);
                    ctx.lineTo(n.x, n.y + 15);
                    ctx.lineTo(n.x - 15, n.y);
                    ctx.closePath();
                    ctx.fill();
                    ctx.stroke();
                });
            }

            else if (mode === 'core') {
                ctx.translate(cx, cy);

                // Reactor Core - KEEP FAST for "Knowledge Trees"
                const coreTime = time * 1.5; // Compensate for global slow down to keep original speed (0.01 * 1.5 = 0.015 approx original was 0.01 but visually seems fine to boost back)
                // Actually original was 0.01 global. So (time * 1 / 0.67) restores it.
                const restoreSpeed = time * 1.5;

                const pulse = 1 + Math.sin(restoreSpeed * 5) * 0.1;
                ctx.fillStyle = color;
                ctx.shadowBlur = 30 * pulse;
                ctx.shadowColor = color;
                ctx.beginPath();
                ctx.arc(0, 0, 30, 0, Math.PI*2);
                ctx.fill();
                ctx.shadowBlur = 0;

                // Spinning Containment Rings
                coreRings.forEach((r, i) => {
                    ctx.save();
                    const radius = 60 + i * 30;
                    // Rotate alternating directions
                    ctx.rotate(restoreSpeed * (i % 2 === 0 ? 1 : -1) * (1 - i * 0.1));

                    ctx.strokeStyle = color;
                    ctx.globalAlpha = 0.3;
                    ctx.lineWidth = 2;

                    // Draw Ring Arcs
                    ctx.beginPath();
                    ctx.arc(0, 0, radius, 0, Math.PI * 1.5);
                    ctx.stroke();

                    // Tech detail
                    ctx.fillStyle = '#fff';
                    ctx.fillRect(radius - 2, -2, 4, 4);

                    ctx.restore();
                });

                ctx.setTransform(1,0,0,1,0,0);
            }

            else if (mode === 'shield') {
                ctx.translate(cx, cy);
                shieldHexes.forEach(h => {
                    // Random activation
                    if (Math.random() > 0.99) h.active = 1;
                    h.active *= 0.96; // Slower decay (was 0.95)

                    ctx.strokeStyle = color;
                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.1 + h.active;

                    // Draw Hex
                    ctx.beginPath();
                    for(let i=0; i<6; i++) {
                        const a = Math.PI/3 * i;
                        const hx = h.x + Math.cos(a) * 10;
                        const hy = h.y + Math.sin(a) * 10;
                        if(i===0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
                    }
                    ctx.closePath();
                    ctx.stroke();
                    if (h.active > 0.1) ctx.fill();
                });
                ctx.globalAlpha = 1;
                ctx.setTransform(1,0,0,1,0,0);
            }

            else if (mode === 'swarm') {
                // Spawn new pings
                if (Math.random() > 0.96) { // Less frequent (was 0.95)
                    swarmPings.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        life: 0,
                        maxR: 30 + Math.random() * 50
                    });
                }

                // Process Pings
                for (let i = swarmPings.length - 1; i >= 0; i--) {
                    const p = swarmPings[i];
                    p.life += 0.0067; // Slower growth (was 0.01)
                    if (p.life > 1) {
                        swarmPings.splice(i, 1);
                        continue;
                    }

                    // Draw Ping Ripple
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 2 * (1 - p.life);
                    ctx.globalAlpha = 1 - p.life;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.maxR * p.life, 0, Math.PI*2);
                    ctx.stroke();

                    // Draw Center Dot
                    ctx.fillStyle = '#fff';
                    ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI*2); ctx.fill();

                    // Connect Neighbors
                    for (let j = i + 1; j < swarmPings.length; j++) {
                        const p2 = swarmPings[j];
                        const dx = p.x - p2.x;
                        const dy = p.y - p2.y;
                        const dist = Math.sqrt(dx*dx + dy*dy);
                        if (dist < 100) {
                            ctx.strokeStyle = color;
                            ctx.lineWidth = 1;
                            ctx.globalAlpha = (1 - dist/100) * 0.5;
                            ctx.beginPath();
                            ctx.moveTo(p.x, p.y);
                            ctx.lineTo(p2.x, p2.y);
                            ctx.stroke();
                        }
                    }
                }
                ctx.globalAlpha = 1;
            }

            else if (mode === 'predictive') {
                ctx.lineWidth = 2;
                predPaths.forEach((p, i) => {
                    ctx.beginPath();
                    ctx.strokeStyle = i === 2 ? color : 'rgba(255,255,255,0.1)'; 

                    for(let x=0; x<w; x+=5) {
                        const progress = x/w;
                        const divergence = progress * progress * 100 * p.offset;
                        const y = h/2 
                            + Math.sin(x * 0.02 - time * 5) * 40 
                            + Math.sin(time * 3 + p.phase) * divergence;

                        if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
                    }
                    ctx.stroke();
                });

                // Vertical analysis scanner
                const scanX = (time * 100) % w; // Slower scan (was 150)
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(scanX, 0, 30, h);
                ctx.globalAlpha = 1;
            }

            else if (mode === 'translation') {
                ctx.font = '10px monospace';
                const split = w * 0.6;

                transParticles.forEach(p => {
                    p.y += p.speed;
                    if (p.y > h) p.y = 0;

                    if (p.x < split) {
                        // Chaos Matrix
                        ctx.fillStyle = 'rgba(255,255,255,0.2)';
                        ctx.fillText(p.char, p.x, p.y);
                    } else {
                        // Order Grid
                        ctx.fillStyle = color;
                        const gx = Math.floor(p.x / 20) * 20;
                        const gy = Math.floor(p.y / 10) * 10;
                        ctx.fillRect(gx, gy, 15, 2);
                    }
                });

                // The Filter Line
                ctx.beginPath();
                ctx.moveTo(split, 0); ctx.lineTo(split, h);
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            else if (mode === 'identity') {
                ctx.translate(cx, cy);
                ctx.rotate(-time * 0.2);

                identPoints.forEach((p, i) => {
                    // Fingerprint-like spiral logic
                    const r = p.dist + Math.sin(time * 3 + i * 0.1) * 2;
                    const x = Math.cos(p.angle) * r;
                    const y = Math.sin(p.angle) * r;

                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.5 + Math.sin(time * 5 + p.pulse) * 0.5;
                    ctx.beginPath();
                    ctx.arc(x, y, 1.5, 0, Math.PI*2);
                    ctx.fill();
                });
                ctx.globalAlpha = 1;
                ctx.setTransform(1,0,0,1,0,0);

                // Radar sweep
                const angle = time * 2;
                ctx.translate(cx, cy);
                ctx.rotate(angle);
                const g = ctx.createLinearGradient(0,0,150,0);
                g.addColorStop(0, 'rgba(0,0,0,0)');
                g.addColorStop(1, color); // tip
                ctx.fillStyle = g;
                ctx.beginPath();
                ctx.moveTo(0,0); ctx.arc(0,0,150,0, 0.2); ctx.fill();
                ctx.setTransform(1,0,0,1,0,0);
            }

            frameId = requestAnimationFrame(render);
        };
        render();

        return () => cancelAnimationFrame(frameId);
    }, [mode, color]);

    return (
        <div className="w-full h-full relative overflow-hidden bg-black/20">
            <canvas 
                ref={canvasRef} 
                width={400} 
                height={400} 
                className="w-full h-full object-cover opacity-80 mix-blend-screen"
            />
            {/* Scanline Overlay */}
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ background: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

const LogisticsHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.parentElement?.clientWidth || window.innerWidth;
        let h = canvas.parentElement?.clientHeight || window.innerHeight;
        let frame = 0;
        let frameId: number;

        const PHASE_DURATION = 900; 

        // --- 1. INDUCTION (Packages) ---
        interface PackageBox { x: number, y: number, w: number, h: number, speed: number, type: 'standard' | 'priority' | 'hazardous' }
        const packages: PackageBox[] = [];
        for(let i=0; i<100; i++) {
            packages.push({
                x: Math.random() * w * 1.5,
                y: Math.random() * h,
                w: 20 + Math.random() * 30,
                h: 10 + Math.random() * 20,
                speed: (1.8 + Math.random() * 2.7) * 0.67, // SLOWED
                type: Math.random() > 0.9 ? 'hazardous' : Math.random() > 0.8 ? 'priority' : 'standard'
            });
        }

        // --- 2. NETWORK (Globe) ---
        interface GlobePoint { x: number, y: number, z: number, r: number }
        const globePoints: GlobePoint[] = [];
        const count = 600;
        const r = 250;
        const phi = Math.PI * (3 - Math.sqrt(5));
        for(let i=0; i<count; i++) {
            const y = 1 - (i / (count - 1)) * 2;
            const radius = Math.sqrt(1 - y * y);
            const theta = phi * i;
            const x = Math.cos(theta) * radius;
            const z = Math.sin(theta) * radius;
            globePoints.push({ x: x*r, y: y*r, z: z*r, r: Math.random() > 0.95 ? 3 : 1.5 });
        }

        // --- 3. SORTATION (Radial) ---
        interface SortParticle { r: number, angle: number, speed: number, color: string }
        const sortParticles: SortParticle[] = [];
        for(let i=0; i<150; i++) {
            sortParticles.push({
                r: Math.random() * 50,
                angle: Math.random() * Math.PI * 2,
                speed: (1.8 + Math.random() * 3.6) * 0.67, // SLOWED
                color: Math.random() > 0.5 ? '#10b981' : '#f59e0b'
            });
        }

        const render = () => {
            frame++;
            const cycle = frame % (PHASE_DURATION * 3);
            let activePhase = 0;

            if (cycle < PHASE_DURATION) activePhase = 0;
            else if (cycle < PHASE_DURATION * 2) activePhase = 1;
            else activePhase = 2;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            if (activePhase === 0) {
                // --- INDUCTION BATCHED ---
                packages.forEach(p => {
                    p.x -= p.speed;
                    if (p.x < -100) { p.x = w + Math.random() * 200; p.y = Math.random() * h; }
                });

                // Batch 1: Standard (Cyan)
                ctx.fillStyle = '#06b6d4';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'standard') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // Batch 2: Priority (Amber)
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'priority') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // Batch 3: Hazardous (Red)
                ctx.fillStyle = '#ef4444';
                ctx.beginPath();
                for (const p of packages) {
                    if (p.type === 'hazardous') ctx.rect(p.x, p.y, p.w, p.h);
                }
                ctx.fill();

                // 3D Sides (Batch)
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.beginPath();
                for (const p of packages) {
                    ctx.moveTo(p.x, p.y); 
                    ctx.lineTo(p.x+10, p.y-10); 
                    ctx.lineTo(p.x+p.w+10, p.y-10); 
                    ctx.lineTo(p.x+p.w, p.y);
                }
                ctx.fill();

            } else if (activePhase === 1) {
                // --- GLOBE BATCHED ---
                ctx.save();
                ctx.translate(w * 0.75, h * 0.5);
                const time = frame * 0.003; // SLOWED from 0.0045
                const cosT = Math.cos(time);
                const sinT = Math.sin(time);

                const bluePoints: number[] = []; 
                const amberPoints: number[] = []; 

                for (let i = 0; i < globePoints.length; i++) {
                    const p = globePoints[i];
                    let x = p.x * cosT - p.z * sinT;
                    let z = p.z * cosT + p.x * sinT;

                    if (z > -200) {
                        const scale = 500 / (500 + z);
                        const size = p.r * scale;
                        const px = x * scale;
                        const py = p.y * scale;

                        if (p.r > 2) {
                            amberPoints.push(px, py, size);
                        } else {
                            bluePoints.push(px, py, size);
                        }
                    }
                }

                // Draw Blue
                ctx.fillStyle = '#06b6d4';
                ctx.beginPath();
                for(let i=0; i<bluePoints.length; i+=3) {
                    ctx.rect(bluePoints[i], bluePoints[i+1], bluePoints[i+2], bluePoints[i+2]);
                }
                ctx.fill();

                // Draw Amber
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for(let i=0; i<amberPoints.length; i+=3) {
                    ctx.rect(amberPoints[i], amberPoints[i+1], amberPoints[i+2], amberPoints[i+2]);
                }
                ctx.fill();

                ctx.restore();

            } else {
                // --- SORTATION BATCHED ---
                ctx.save();
                ctx.translate(w * 0.75, h * 0.5);

                const greenParticles: number[] = [];
                const amberParticles: number[] = [];

                for (let i = 0; i < sortParticles.length; i++) {
                    const p = sortParticles[i];
                    p.r += p.speed;
                    p.angle += 0.03; // SLOWED from 0.045
                    if (p.r > 300) { p.r = 60; p.angle = Math.random() * Math.PI * 2; }

                    const px = Math.cos(p.angle) * p.r;
                    const py = Math.sin(p.angle) * p.r;

                    if (p.color === '#10b981') greenParticles.push(px, py);
                    else amberParticles.push(px, py);
                }

                // Draw Green
                ctx.fillStyle = '#10b981';
                ctx.beginPath();
                for(let i=0; i<greenParticles.length; i+=2) {
                    ctx.rect(greenParticles[i], greenParticles[i+1], 3, 3);
                }
                ctx.fill();

                // Draw Amber
                ctx.fillStyle = '#f59e0b';
                ctx.beginPath();
                for(let i=0; i<amberParticles.length; i+=2) {
                    ctx.rect(amberParticles[i], amberParticles[i+1], 3, 3);
                }
                ctx.fill();

                ctx.restore();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

export const LogisticsHeroVisualizer = React.memo(LogisticsHeroVisualizerComponent);

import React, { useEffect, useRef } from 'react';

const IndustrialsHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width;
        let h = canvas.height;
        let time = 0;
        let frameId: number;

        // --- PERFORMANCE CONTROL ---
        let lastTime = 0;
        const TARGET_FPS = 60;
        const FRAME_INTERVAL = 1000 / TARGET_FPS;

        const CAM_Z = 600;
        let CX = w * 0.65;
        let CY = h * 0.5;
        const MODEL_SCALE = 1.4;

        interface Point { x: number, y: number, z: number }
        // Pre-calculate geometry once
        const parts: { points: Point[], rotationSpeed: number, color: string, type: 'casing' | 'rotor' }[] = [];

        // 1. CASING (Static Geometry)
        const casingPoints: Point[] = [];
        for (let z = -250; z <= 250; z += 40) {
            const r = (130 + Math.sin(z * 0.008) * 15) * MODEL_SCALE;
            for (let a = 0; a < Math.PI * 2; a += 0.3) {
                casingPoints.push({ x: Math.cos(a) * r, y: Math.sin(a) * r, z: z });
            }
        }
        parts.push({ points: casingPoints, rotationSpeed: 0.001, color: 'rgba(255, 255, 255, 0.15)', type: 'casing' });

        // 2. ROTORS (Dynamic Geometry)
        for (let i = 0; i < 6; i++) {
            const z = -200 + i * 80;
            const pts: Point[] = [];
            const rOuter = 115 * MODEL_SCALE;
            const bladeCount = 8 + (i%2)*4; 

            for (let b = 0; b < bladeCount; b++) {
                const angle = (Math.PI * 2 / bladeCount) * b;
                pts.push({ x: Math.cos(angle) * 40 * MODEL_SCALE, y: Math.sin(angle) * 40 * MODEL_SCALE, z });
                pts.push({ x: Math.cos(angle + 0.3) * rOuter, y: Math.sin(angle + 0.3) * rOuter, z });
            }
            parts.push({ points: pts, rotationSpeed: 0.08 * (i%2===0?1:-1), color: 'rgba(245, 158, 11, 0.8)', type: 'rotor' }); // SLOWED from 0.13
        }

        const render = (timestamp: number) => {
            frameId = requestAnimationFrame(render);

            const deltaTime = timestamp - lastTime;
            if (deltaTime < FRAME_INTERVAL) return;
            lastTime = timestamp - (deltaTime % FRAME_INTERVAL);

            time += 0.006; // SLOWED from 0.009

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const camRotY = time * 0.2;
            const camRotX = Math.sin(time * 0.25) * 0.15;

            const cosCY = Math.cos(camRotY), sinCY = Math.sin(camRotY);
            const cosCX = Math.cos(camRotX), sinCX = Math.sin(camRotX);

            for(let j=0; j<parts.length; j++) {
                const part = parts[j];
                const currentRot = time * part.rotationSpeed * 50;
                const cosR = Math.cos(currentRot);
                const sinR = Math.sin(currentRot);

                ctx.beginPath();
                ctx.strokeStyle = part.color;
                ctx.fillStyle = part.color;

                const pts = part.points;
                const len = pts.length;

                for (let i = 0; i < len; i++) {
                    const p = pts[i];
                    let x = p.x, y = p.y, z = p.z;

                    if (part.type === 'rotor') {
                        const nx = x * cosR - y * sinR;
                        const ny = x * sinR + y * cosR;
                        x = nx; y = ny;
                    }

                    const tx = x * cosCY - z * sinCY;
                    const tz = z * cosCY + x * sinCY;
                    x = tx; z = tz;

                    const ty = y * cosCX - z * sinCX;
                    const tz2 = z * cosCX + y * sinCX;
                    y = ty; z = tz2;

                    const scale = CAM_Z / (CAM_Z + z);

                    if (scale > 0) {
                        const px = CX + x * scale;
                        const py = CY + y * scale;

                        if (part.type === 'rotor') {
                            if (i % 2 === 0) ctx.moveTo(px, py); 
                            else ctx.lineTo(px, py);
                        } else {
                            ctx.rect(px, py, 1.5 * scale, 1.5 * scale);
                        }
                    }
                }

                if (part.type === 'rotor') {
                    ctx.stroke();
                } else {
                    ctx.fill();
                }
            }
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                w = canvas.width = rect.width;
                h = canvas.height = rect.height;
                CX = w * 0.65;
                CY = h * 0.5;
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        frameId = requestAnimationFrame(render);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

