        let cx = 0;
        let cy = 0;

        let frameId: number;
        let time = 0;

        const CAM_Z = 600;
        const MODEL_SCALE = 1.4;

        // --- GEOMETRY PRE-CALCULATION ---
        // Using flat arrays for [x, y, z] is faster than objects
        // Structure: [x, y, z, x, y, z...]

        const createCasing = () => {
            const verts: number[] = [];
            for (let z = -250; z <= 250; z += 40) { // Reduced density for performance
                const r = (130 + Math.sin(z * 0.008) * 15) * MODEL_SCALE;
                for (let a = 0; a < Math.PI * 2; a += 0.3) {
                    verts.push(Math.cos(a) * r, Math.sin(a) * r, z);
                }
            }
            return new Float32Array(verts);
        };

        const createRotor = () => {
            const verts: number[] = [];
            // Single rotor blade shape
            const rOuter = 115 * MODEL_SCALE;
            const rInner = 40 * MODEL_SCALE;

            // We'll rotate this single definition in the render loop
            // Define points: Inner, Outer
            verts.push(rInner, 0, 0); // Inner 1
            verts.push(rOuter, 10, 0); // Outer 1 (twisted)
            return new Float32Array(verts);
        };

        const casing = createCasing();
        const rotorTemplate = createRotor();

        // Config for the 6 stages
        const STAGES = 6;
        const STAGE_SPACING = 80;
        const STAGE_OFFSET = -200;

        const render = () => {
            time += 0.005; // Base Speed

            // Clear
            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            // Camera Rotation Matrices
            const rotY = time * 0.2;
            const rotX = Math.sin(time * 0.25) * 0.15;
            const cy_cos = Math.cos(rotY), cy_sin = Math.sin(rotY);
            const cx_cos = Math.cos(rotX), cx_sin = Math.sin(rotX);

            // --- DRAW CASING ---
            ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.beginPath();

            for (let i = 0; i < casing.length; i += 3) {
                const x = casing[i];
                const y = casing[i+1];
                const z = casing[i+2];

                // Camera Transform
                const tx = x * cy_cos - z * cy_sin;
                const tz = z * cy_cos + x * cy_sin;

                const ty = y * cx_cos - tz * cx_sin;
                const tz2 = tz * cx_cos + y * cx_sin;

                const scale = CAM_Z / (CAM_Z + tz2);

                if (scale > 0) {
                    const px = cx + tx * scale;
                    const py = cy + ty * scale;
                    // Optimization: Draw tiny rects instead of arc for massive speedup
                    ctx.rect(px, py, 1.5 * scale, 1.5 * scale);
                }
            }
            ctx.fill();

            // --- DRAW ROTORS ---
            for (let s = 0; s < STAGES; s++) {
                const zPos = STAGE_OFFSET + s * STAGE_SPACING;
                // Alternating rotation directions
                const dir = s % 2 === 0 ? 1 : -1;
                const rotorAngle = time * 2.5 * dir; // Speed multiplier

                const r_cos = Math.cos(rotorAngle);
                const r_sin = Math.sin(rotorAngle);

                const bladeCount = 12 + (s % 2) * 4;
                const angleStep = (Math.PI * 2) / bladeCount;

                ctx.beginPath();
                ctx.strokeStyle = 'rgba(245, 158, 11, 0.6)'; // Amber
                ctx.lineWidth = 1;

                // Draw all blades for this stage
                for (let b = 0; b < bladeCount; b++) {
                    const bladeAngle = b * angleStep;
                    const b_cos = Math.cos(bladeAngle);
                    const b_sin = Math.sin(bladeAngle);

                    // Inner Point (Rotated by Blade Index then by Rotor Spin)
                    // Simplified: We know inner is at r=40, z=zPos
                    const rInner = 40 * MODEL_SCALE;
                    const rOuter = 115 * MODEL_SCALE;

                    // Compute world positions
                    // 1. Blade Local Rotation
                    // 2. Rotor Spin
                    // 3. Camera Transform

                    // Optimization: Combine blade and rotor angles
                    const totalAngle = rotorAngle + bladeAngle;
                    const t_cos = Math.cos(totalAngle);
                    const t_sin = Math.sin(totalAngle);
                    const t_cos_twist = Math.cos(totalAngle + 0.3); // Twist for outer
                    const t_sin_twist = Math.sin(totalAngle + 0.3);

                    // Inner Vertex
                    const ix = rInner * t_cos;
                    const iy = rInner * t_sin;
                    const iz = zPos;

                    // Outer Vertex
                    const ox = rOuter * t_cos_twist;
                    const oy = rOuter * t_sin_twist;
                    const oz = zPos;

                    // Camera Transform - Inner
                    let itx = ix * cy_cos - iz * cy_sin;
                    let itz = iz * cy_cos + ix * cy_sin;
                    let ity = iy * cx_cos - itz * cx_sin;
                    let itz2 = itz * cx_cos + iy * cx_sin;

                    // Camera Transform - Outer
                    let otx = ox * cy_cos - oz * cy_sin;
                    let otz = oz * cy_cos + ox * cy_sin;
                    let oty = oy * cx_cos - otz * cx_sin;
                    let otz2 = otz * cx_cos + oy * cx_sin;

                    const iScale = CAM_Z / (CAM_Z + itz2);
                    const oScale = CAM_Z / (CAM_Z + otz2);

                    if (iScale > 0 && oScale > 0) {
                        ctx.moveTo(cx + itx * iScale, cy + ity * iScale);
                        ctx.lineTo(cx + otx * oScale, cy + oty * oScale);
                    }
                }
                ctx.stroke();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                width = rect.width;
                height = rect.height;
                cx = width * 0.65;
                cy = height * 0.5;
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        frameId = requestAnimationFrame(render);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{width: '100%', height: '100%'}} />;
};

import React, { useEffect, useRef } from 'react';

export const ResourcesHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frame = 0;
        let animationFrameId: number;

        // Optimization: Object pooling for extractions
        const MAX_EXTRACTIONS = 20;
        const extractions: Float32Array = new Float32Array(MAX_EXTRACTIONS * 5); // x, y, life, colorIndex, codeIndex
        // Using index to reference static color/code arrays to avoid string allocs
        for(let i=0; i<MAX_EXTRACTIONS; i++) extractions[i*5 + 2] = 0; // Set life to 0 (inactive)

        const NODE_COLORS = ['#f59e0b', '#06b6d4', '#d946ef', '#ef4444', '#10b981', '#f43f5e'];

        const spawnExtraction = (x: number, y: number, colorIdx: number) => {
            for (let i = 0; i < MAX_EXTRACTIONS; i++) {
                if (extractions[i*5 + 2] <= 0) {
                    extractions[i*5] = x;
                    extractions[i*5+1] = y;
                    extractions[i*5+2] = 1.0; // Life
                    extractions[i*5+3] = colorIdx;
                    extractions[i*5+4] = Math.random(); // Random Code Seed
                    break;
                }
            }
        };

        const render = () => {
            frame++;
            const time = frame * 0.013;
            const scroll = frame * 1.3;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const lines = 40; // Reduced slightly for perf
            const step = height / lines;
            const scanX = (time * 200) % (width + 400) - 200;

            // 1. Draw Strata Lines
            // Optimized: Fewer sine calls, simple arithmetic
            ctx.lineWidth = 1.5;

            for (let i = 0; i < lines; i++) {
                const yBase = i * step + step/2;
                const hue = 150 + (i / lines) * 80;

                ctx.beginPath();
                ctx.strokeStyle = `hsla(${hue}, 60%, 50%, 0.15)`; // Base color

                // Dynamic Scan Logic
                const isInScan = scanX > -100 && scanX < width + 100;
                if (isInScan) {
                    // Create gradient only if near scan
                    const grad = ctx.createLinearGradient(scanX - 100, 0, scanX + 100, 0);
                    grad.addColorStop(0, `hsla(${hue}, 60%, 50%, 0.1)`);
                    grad.addColorStop(0.5, `hsla(${hue}, 90%, 80%, 0.8)`);
                    grad.addColorStop(1, `hsla(${hue}, 60%, 50%, 0.1)`);
                    ctx.strokeStyle = grad;
                }

                // Draw Line Segment
                // Increment x by 8 instead of 6 for 25% fewer points
                for (let x = 0; x < width; x += 8) {
                    const worldX = x + scroll;

                    // Simple noise approximation
                    const base = Math.sin(worldX * 0.003 + i * 0.05) * 30;
                    const detail = Math.cos(worldX * 0.01 + time * 0.5) * 8;

                    const distToScan = Math.abs(x - scanX);
                    // Optimized scan influence (no Math.max inside loop if possible)
                    const scanInfluence = distToScan < 80 ? (1 - distToScan / 80) * 5 : 0;

                    const y = yBase + base + detail - scanInfluence;

                    if (x === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            // 2. Resource Nodes
            const dotCount = 8;
            const sectionWidth = width / dotCount;

            for(let j=0; j<dotCount; j++) {
                const colorIdx = j % NODE_COLORS.length;
                const nodeColor = NODE_COLORS[colorIdx];

                const dx = (j * sectionWidth + (sectionWidth/2)) % width;
                const dy = (height * 0.4) + Math.sin(frame * 0.02 + j * 100) * (height * 0.2);

                const distToScan = Math.abs(dx - scanX);

                // Trigger?
                if (distToScan < 5 && Math.random() > 0.98) {
                    spawnExtraction(dx, dy, colorIdx);
                }

                if (distToScan < 70) {
                    ctx.fillStyle = nodeColor;
                    ctx.shadowColor = nodeColor;
                    ctx.shadowBlur = 15;
                    const pulse = 1 + Math.sin(frame * 0.2) * 0.3;
                    ctx.beginPath(); ctx.arc(dx, dy, 3 * pulse, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                } else {
                    ctx.strokeStyle = `rgba(255,255,255,0.1)`;
                    ctx.beginPath(); ctx.arc(dx, dy, 1.5, 0, Math.PI*2); ctx.stroke();
                }
            }

            // 3. Render Extractions
            for (let i = 0; i < MAX_EXTRACTIONS; i++) {
                const life = extractions[i*5 + 2];
                if (life <= 0) continue;

                // Decay
                extractions[i*5 + 2] -= 0.012;

                const x = extractions[i*5];
                const y = extractions[i*5 + 1];
                const color = NODE_COLORS[extractions[i*5 + 3]];
                const code = Math.floor(extractions[i*5 + 4] * 1000);

                const beamAlpha = Math.sin(life * Math.PI) * 0.6;

                // Beam
                ctx.save();
                ctx.globalAlpha = beamAlpha;
                ctx.fillStyle = color;
                ctx.fillRect(x - 1, 0, 2, y);
                ctx.restore();

                // Packet
                const travelY = y - (Math.pow(1 - life, 2) * y);
                ctx.fillStyle = '#fff';
                ctx.fillRect(x - 2, travelY - 2, 4, 4);

                // Text
                if (life > 0.4) {
                    ctx.fillStyle = color;
                    ctx.globalAlpha = beamAlpha;
                    ctx.font = '10px monospace';
                    ctx.fillText(`[${code}]`, x + 8, travelY);
                    ctx.globalAlpha = 1;
                }
            }

            animationFrameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{width: '100%', height: '100%'}} />;
};

import React, { useEffect, useRef } from 'react';

export const HealthcareHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let time = 0;
        let frameId: number;

        const BASE_PAIRS = 45; 
        const ROTATION_SPEED = 0.013;

        // Pre-calculate helix positions (normalized -1 to 1)
        // We only calculate x/z relations once, then scale/rotate in render
        const helixMap = new Float32Array(BASE_PAIRS * 2); // angle, offset
        for(let i=0; i<BASE_PAIRS; i++) {
            helixMap[i*2] = i * 0.4; // angle offset
            helixMap[i*2+1] = i; // linear offset index
        }

        const render = () => {
            time += 0.9;
            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cy = height / 2;
            const amplitude = 80;
            // Responsive spacing based on width
            const spacing = width / (BASE_PAIRS - 4);
            const scanX = (time * 3) % (width + 300) - 150;

            // Batch arrays
            ctx.lineWidth = 1;

            for (let i = 0; i < BASE_PAIRS; i++) {
                // Calculate X position with wrapping for infinite scroll illusion
                const xBase = (i * spacing + time * 0.5) % (width + spacing * 4) - spacing * 2;

                // Skip off-screen
                if (xBase < -50 || xBase > width + 50) continue;

                // Dynamic calculations
                const angle = helixMap[i*2] + time * ROTATION_SPEED;

                const sinA = Math.sin(angle);
                const cosA = Math.cos(angle); // Z-depth

                const y1 = cy + sinA * amplitude;
                const y2 = cy + Math.sin(angle + Math.PI) * amplitude; // Opposite strand

                const z1 = cosA; // 1 to -1
                const z2 = -cosA;

                // Scan Logic
                const distToScan = Math.abs(xBase - scanX);
                const isScanned = distToScan < 80;
                const scanIntensity = isScanned ? (1 - distToScan / 80) : 0;

                // Color
                // Base Teal: rgba(20, 184, 166, ...)
                // Scanned White: rgba(255, 255, 255, ...)

                const alphaBase = 0.2 + (z1 + 1) * 0.3; // Depth fog

                // --- DRAW CONNECTION ---
                ctx.beginPath();
                ctx.moveTo(xBase, y1);
                ctx.lineTo(xBase, y2);
                if (isScanned) {
                    ctx.strokeStyle = `rgba(255, 255, 255, ${scanIntensity * 0.8})`;
                    ctx.lineWidth = 2;
                } else {
                    ctx.strokeStyle = 'rgba(20, 184, 166, 0.15)';
                    ctx.lineWidth = 1;
                }
                ctx.stroke();

                // --- DRAW NODES ---
                const drawNode = (y: number, z: number) => {
                    const scale = 1 + z * 0.3;
                    const size = 3 * scale;

                    ctx.beginPath();
                    ctx.arc(xBase, y, size, 0, Math.PI * 2);

                    if (isScanned) {
                        ctx.fillStyle = `rgba(255, 255, 255, ${Math.max(alphaBase, scanIntensity)})`;
                    } else {
                        ctx.fillStyle = `rgba(45, 212, 191, ${alphaBase})`;
                    }
                    ctx.fill();
                };

                drawNode(y1, z1);
                drawNode(y2, z2);
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{width: '100%', height: '100%'}} />;
};

