            let ty = y * Math.cos(tiltX) - z * Math.sin(tiltX);
            let tz = z * Math.cos(tiltX) + y * Math.sin(tiltX);
            y = ty; z = tz;

            let tx = x * Math.cos(tiltZ) - y * Math.sin(tiltZ);
            ty = y * Math.cos(tiltZ) + x * Math.sin(tiltZ);
            x = tx; y = ty;

