                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                // Project
                const scale = CAM_Z / (CAM_Z + z);

                if (scale > 0) {
                    const px = cx + x * scale;
                    const py = cy + y * scale;
                    const size = (phase === 1 ? 1.8 : 1.4) * scale;
