                    else { batchCyan.push(px, py, size); }
                }
            }

            // Draw Batches
            const drawBatch = (list: number[], color: string) => {
                if (list.length === 0) return;
                ctx.fillStyle = color;
                ctx.beginPath();
                for (let k = 0; k < list.length; k+=3) {
                    ctx.moveTo(list[k], list[k+1]);
                    ctx.arc(list[k], list[k+1], list[k+2], 0, Math.PI * 2);
                }
                ctx.fill();
            };

            drawBatch(batchCyan, '#06b6d4');
            drawBatch(batchAmber, '#f59e0b');
            drawBatch(batchWhite, '#ffffff');

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                width = rect.width;
                height = rect.height;

                // Re-init map targets to fit new width
                updateTargets();
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
