        const PHASE_DURATION = 500;
        const TRANSITION_SPEED = 0.03;

        // --- STATE ---
        // Layout: [x, y, z, tx, ty, tz, colorType(0-1)]
        const P_STRIDE = 7;
        const data = new Float32Array(PARTICLE_COUNT * P_STRIDE);

        // Initialize with random start positions
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            data[idx] = (Math.random() - 0.5) * 2000;
            data[idx+1] = (Math.random() - 0.5) * 2000;
            data[idx+2] = (Math.random() - 0.5) * 2000;

            // Color variation: 0=Cyan, 1=Amber, 2=White
            const rand = Math.random();
            data[idx+6] = rand > 0.9 ? 1 : (rand > 0.7 ? 2 : 0);
        }

        let phase = 0; 
        let phaseTimer = 0;

        // --- GEOMETRY GENERATORS ---

        // PHASE 0: THE LEDGER (Flat Wave)
        const setTargetPlane = () => {
            const spacingX = 40;
            const spacingY = 40;
            const offsetX = (COLS * spacingX) / 2;
            const offsetY = (ROWS * spacingY) / 2;

            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);

                const tx = col * spacingX - offsetX;
                const ty = row * spacingY - offsetY;
                // Sine wave ripple based on position
                const tz = Math.sin(col * 0.2) * 50 + Math.cos(row * 0.2) * 50;

                data[idx+3] = tx;
                data[idx+4] = ty;
                data[idx+5] = tz;
            }
        };

        // PHASE 1: THE GLOBE (Sphere)
        const setTargetSphere = () => {
            const radius = 280;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);

                // Map grid directly to sphere coordinates (UV mapping)
                const lat = (row / (ROWS - 1)) * Math.PI - Math.PI / 2; // -90 to 90
                const lon = (col / (COLS - 1)) * Math.PI * 2; // 0 to 360

                const tx = radius * Math.cos(lat) * Math.cos(lon);
                const ty = radius * Math.sin(lat);
                const tz = radius * Math.cos(lat) * Math.sin(lon);

                data[idx+3] = tx;
                data[idx+4] = ty;
                data[idx+5] = tz;
            }
        };

        // PHASE 2: THE FLOW (Torus)
        const setTargetTorus = () => {
            const R = 240; // Major radius (distance from center of tube to center of torus)
            const r = 80;  // Minor radius (radius of the tube)

            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);

                const u = (col / COLS) * Math.PI * 2; // Angle around the main ring
                const v = (row / ROWS) * Math.PI * 2; // Angle around the tube

                const tx = (R + r * Math.cos(v)) * Math.cos(u);
                const ty = (R + r * Math.cos(v)) * Math.sin(u);
                const tz = r * Math.sin(v);

                data[idx+3] = tx;
                data[idx+4] = ty;
                data[idx+5] = tz;
            }
        };

        const updateTargets = () => {
            if (phase === 0) setTargetPlane();
            else if (phase === 1) setTargetSphere();
            else setTargetTorus();
        };

        // Init
        setTargetPlane();

        // --- RENDER LOOP ---
        const render = () => {
            time += 0.01;
            phaseTimer++;

            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            // Background
            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            // Camera Rotation
            // We rotate the entire object to show off the 3D structure
            const rotY = time * 0.3;
            const rotX = Math.sin(time * 0.2) * 0.2;
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // BATCH DRAWING: CONNECTIONS
            // We draw lines between grid neighbors to create the "Fabric" effect
            ctx.lineWidth = 0.5;

            // To save performance, we project first, then draw lines
            // We'll store projected 2D coordinates
            const projX = new Float32Array(PARTICLE_COUNT);
            const projY = new Float32Array(PARTICLE_COUNT);
            const projScale = new Float32Array(PARTICLE_COUNT); // Used for culling

            // 1. UPDATE & PROJECT
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP
                data[idx] += (data[idx+3] - data[idx]) * TRANSITION_SPEED;
                data[idx+1] += (data[idx+4] - data[idx+1]) * TRANSITION_SPEED;
                data[idx+2] += (data[idx+5] - data[idx+2]) * TRANSITION_SPEED;

                // Wave effect for Plane Phase only
                let x = data[idx];
                let y = data[idx+1];
                let z = data[idx+2];

                if (phase === 0) {
                    z += Math.sin(x * 0.05 + time * 3) * 15;
                }

                // 3D Rotation
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                const scale = CAM_Z / (CAM_Z + z);
                projScale[i] = scale;

                if (scale > 0) {
                    projX[i] = cx + x * scale;
                    projY[i] = cy + y * scale;
                }
            }

            // 2. DRAW MESH LINES (The "Network" Link)
            // We draw horizontal and vertical grid lines
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(6, 182, 212, 0.15)'; // Faint Cyan

            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const i = r * COLS + c;
                    if (projScale[i] <= 0) continue;

                    // Horizontal Neighbor (i + 1)
                    if (c < COLS - 1) {
                        const right = i + 1;
                        if (projScale[right] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[right], projY[right]);
                        }
                    }

                    // Vertical Neighbor (i + COLS)
                    if (r < ROWS - 1) {
                        const down = i + COLS;
                        if (projScale[down] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[down], projY[down]);
                        }
                    }
                }
            }
            ctx.stroke();

            // 3. DRAW NODES (The Data)
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const scale = projScale[i];

                if (scale > 0) {
                    const px = projX[i];
                    const py = projY[i];
                    const colorType = data[idx+6];

                    // Size pulsates slightly
                    const size = (1.2 + Math.sin(time * 5 + i) * 0.3) * scale;

                    if (colorType === 1) ctx.fillStyle = '#f59e0b'; // Amber
                    else if (colorType === 2) ctx.fillStyle = '#ffffff'; // White
                    else ctx.fillStyle = '#06b6d4'; // Cyan

