                    ctx.fillRect(px - size/2, py - size/2, size, size);
                }
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                width = rect.width;
                height = rect.height;

                updateTargets();
            }
        };

        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        // --- CONFIG ---
        const PARTICLE_COUNT = 800;
        const CAM_Z = 900;

        // --- DATA STRUCTURE ---
        // [x, y, z, tx, ty, tz, colorType, sizeBase]
        const P_STRIDE = 8;
        const particles = new Float32Array(PARTICLE_COUNT * P_STRIDE);
        const COLORS = ['#8b5cf6', '#a78bfa', '#22d3ee', '#c4b5fd'];

        let phase = 0; // 0: CLOUD, 1: SPHERE, 2: CUBE
        let phaseTimer = 0;
        const PHASE_DURATION = 450; 
        const TRANSITION_SPEED = 0.035;

        // Generators
        const setCloudTargets = () => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.random() * Math.PI * 2;
                const rMain = 250 + Math.random() * 50;
                const rTube = 80 + Math.random() * 40;

                particles[idx + 3] = (rMain + rTube * Math.cos(phi)) * Math.cos(theta); // tx
                particles[idx + 4] = (rMain + rTube * Math.cos(phi)) * Math.sin(theta); // ty
                particles[idx + 5] = rTube * Math.sin(phi); // tz
            }
        };

        const setSphereTargets = () => {
            const radius = 220;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const phi = Math.acos(1 - 2 * (i + 0.5) / PARTICLE_COUNT);
                const theta = Math.sqrt(PARTICLE_COUNT * Math.PI) * phi;

                particles[idx + 3] = radius * Math.cos(theta) * Math.sin(phi);
                particles[idx + 4] = radius * Math.sin(theta) * Math.sin(phi);
                particles[idx + 5] = radius * Math.cos(phi);
            }
        };

        const setCubeTargets = () => {
            const dim = Math.ceil(Math.cbrt(PARTICLE_COUNT));
            const spacing = 45;
            const offset = (dim * spacing) / 2;

            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const x = i % dim;
                const y = Math.floor(i / dim) % dim;
                const z = Math.floor(i / (dim * dim));

                particles[idx + 3] = x * spacing - offset;
                particles[idx + 4] = y * spacing - offset;
                particles[idx + 5] = z * spacing - offset;
            }
        };

        const updateTargets = () => {
             if (phase === 0) setCloudTargets();
             else if (phase === 1) setSphereTargets();
             else setCubeTargets();
        }

        // Initialize
        setCloudTargets(); // Set initial targets
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            // Set current pos to target pos initially
            particles[idx] = particles[idx+3];
            particles[idx+1] = particles[idx+4];
            particles[idx+2] = particles[idx+5];
            // Attributes
            particles[idx+6] = Math.floor(Math.random() * COLORS.length); // Color index
            particles[idx+7] = 0.5 + Math.random(); // Size
        }

        // --- RENDER LOOP ---
        const render = () => {
            time += 0.01;
            phaseTimer++;

            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            // Background
            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75; // Right aligned
            const cy = height * 0.5;

            // Camera Rotation
            const rotY = time * 0.3 + (mouseRef.current.x * 0.5);
            const rotX = Math.sin(time * 0.2) * 0.2 + (mouseRef.current.y * 0.5);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP Position (Smooth Morph)
                particles[idx] += (particles[idx+3] - particles[idx]) * TRANSITION_SPEED;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * TRANSITION_SPEED;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * TRANSITION_SPEED;

                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                // Add "Cloud Noise" only in chaos phase
                if (phase === 0) {
                    x += Math.sin(time * 2 + i) * 2;
                    y += Math.cos(time * 3 + i) * 2;
                }

                // 3D Rotation
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                const scale = CAM_Z / (CAM_Z + z);

                if (scale > 0) {
                    const px = cx + x * scale;
                    const py = cy + y * scale;
                    const size = particles[idx+7] * scale * (phase === 2 ? 3 : 2);
                    const colorIdx = Math.floor(particles[idx+6]);

                    ctx.fillStyle = COLORS[colorIdx];
                    ctx.globalAlpha = Math.min(1, scale * 0.8);

                    if (phase === 2) {
                        ctx.fillRect(px - size/2, py - size/2, size, size);
                    } else {
                        ctx.beginPath();
                        ctx.arc(px, py, size, 0, Math.PI * 2);
                        ctx.fill();
                    }
                }
            }
            ctx.globalAlpha = 1;

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                width = rect.width;
                height = rect.height;

                // Re-init shape to center properly if needed
                updateTargets();
            }
        };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / width) * 2 - 1,
                y: ((e.clientY - rect.top) / height) * 2 - 1
            };
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

