import React, { useEffect, useRef } from 'react';

export const LogisticsHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        // Alpha: false for performance (no composition with background)
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        // --- CONFIG ---
        const COLS = 50; 
        const ROWS = 24;
        const PARTICLE_COUNT = COLS * ROWS; 
        const CAM_Z = 1200;
        const PHASE_DURATION = 600;
        const TRANSITION_SPEED = 0.04;

        // --- STATE & BUFFERS ---
        // Layout: [x, y, z, tx, ty, tz, colorType]
        const P_STRIDE = 7;
        const data = new Float32Array(PARTICLE_COUNT * P_STRIDE);

        // Project buffers (Allocated ONCE to avoid GC)
        const projX = new Float32Array(PARTICLE_COUNT);
        const projY = new Float32Array(PARTICLE_COUNT);
        const projScale = new Float32Array(PARTICLE_COUNT);

        // Initialize state
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            data[idx] = (Math.random() - 0.5) * 2000;
            data[idx+1] = (Math.random() - 0.5) * 2000;
            data[idx+2] = (Math.random() - 0.5) * 2000;

            // Color: 0=Cyan, 1=Amber, 2=White
            const rand = Math.random();
            data[idx+6] = rand > 0.9 ? 1 : (rand > 0.7 ? 2 : 0);
        }

        let phase = 0; 
        let phaseTimer = 0;

        // --- GEOMETRY GENERATORS ---
        const setTargetPlane = () => {
            const spacingX = 35;
            const spacingY = 35;
            const offsetX = (COLS * spacingX) / 2;
            const offsetY = (ROWS * spacingY) / 2;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                data[idx+3] = col * spacingX - offsetX;
                data[idx+4] = row * spacingY - offsetY;
                data[idx+5] = Math.sin(col * 0.2) * 40 + Math.cos(row * 0.2) * 40;
            }
        };

        const setTargetSphere = () => {
            const radius = 300;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const lat = (row / (ROWS - 1)) * Math.PI - Math.PI / 2;
                const lon = (col / (COLS - 1)) * Math.PI * 2;
                data[idx+3] = radius * Math.cos(lat) * Math.cos(lon);
                data[idx+4] = radius * Math.sin(lat);
                data[idx+5] = radius * Math.cos(lat) * Math.sin(lon);
            }
        };

        const setTargetTorus = () => {
            const R = 260; const r = 90;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const u = (col / COLS) * Math.PI * 2;
                const v = (row / ROWS) * Math.PI * 2;
                data[idx+3] = (R + r * Math.cos(v)) * Math.cos(u);
                data[idx+4] = (R + r * Math.cos(v)) * Math.sin(u);
                data[idx+5] = r * Math.sin(v);
            }
        };

        const updateTargets = () => {
            if (phase === 0) setTargetPlane();
            else if (phase === 1) setTargetSphere();
            else setTargetTorus();
        };
        setTargetPlane();

        // --- RENDER LOOP ---
        const render = () => {
            time += 0.015;
            phaseTimer++;
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            // Camera Matrices
            const rotY = time * 0.2;
            const rotX = Math.sin(time * 0.15) * 0.2;
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // 1. UPDATE & PROJECT
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP
                const tx = data[idx+3], ty = data[idx+4], tz = data[idx+5];
                data[idx] += (tx - data[idx]) * TRANSITION_SPEED;
                data[idx+1] += (ty - data[idx+1]) * TRANSITION_SPEED;
                data[idx+2] += (tz - data[idx+2]) * TRANSITION_SPEED;

                let x = data[idx];
                let y = data[idx+1];
                let z = data[idx+2];

                // Wave effect (only phase 0)
                if (phase === 0) z += Math.sin(x * 0.03 + time * 4) * 20;

                // 3D Rotation
                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                let y1 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX;

                const scale = CAM_Z / (CAM_Z + z2);
                projScale[i] = scale;

                if (scale > 0) {
                    projX[i] = cx + x1 * scale;
                    projY[i] = cy + y1 * scale;
                }
            }

            // 2. DRAW CONNECTIONS (Single Batch Path)
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(6, 182, 212, 0.12)'; // Cyan lines
            ctx.lineWidth = 0.8; 

            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const i = r * COLS + c;
                    if (projScale[i] <= 0) continue;

                    // Right Neighbor
                    if (c < COLS - 1) {
                        const right = i + 1;
                        if (projScale[right] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[right], projY[right]);
                        }
                    }
                    // Down Neighbor
                    if (r < ROWS - 1) {
                        const down = i + COLS;
                        if (projScale[down] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[down], projY[down]);
                        }
                    }
                }
            }
            ctx.stroke();

            // 3. DRAW NODES (Batch By Color)
            // Function to draw all nodes of a specific color type
            const drawBatch = (color: string, typeVal: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                for (let i = 0; i < PARTICLE_COUNT; i++) {
                    // Fast check for color type
                    if (Math.abs(data[i * P_STRIDE + 6] - typeVal) > 0.1) continue;
                    if (projScale[i] <= 0) continue;

                    const size = (1.5 + Math.sin(time * 5 + i) * 0.5) * projScale[i];
                    ctx.rect(projX[i] - size/2, projY[i] - size/2, size, size);
                }
                ctx.fill();
            };

            drawBatch('#06b6d4', 0); // Cyan
            drawBatch('#f59e0b', 1); // Amber
            drawBatch('#ffffff', 2); // White

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.parentElement.getBoundingClientRect();
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
                updateTargets();
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        const PARTICLE_COUNT = 900; 
        const CAM_Z = 1000;
        const P_STRIDE = 8;
        const particles = new Float32Array(PARTICLE_COUNT * P_STRIDE);

        // Colors: Violet, Blue, Cyan, White
        const PALETTE = ['#8b5cf6', '#3b82f6', '#22d3ee', '#ffffff'];

        // Init
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            particles[idx] = (Math.random()-0.5) * 500;
            particles[idx+1] = (Math.random()-0.5) * 500;
            particles[idx+2] = (Math.random()-0.5) * 500;
            particles[idx+6] = Math.floor(Math.random() * 4); // Color Index
            particles[idx+7] = 0.5 + Math.random(); // Size
        }

        let phase = 0; 
        let phaseTimer = 0;
        const PHASE_DURATION = 450; 
        const TRANSITION_SPEED = 0.04;

        // Generators
        const setCloudTargets = () => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const r = 250 + Math.random() * 100;
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos((Math.random() * 2) - 1);

                particles[idx+3] = r * Math.sin(phi) * Math.cos(theta);
                particles[idx+4] = r * Math.sin(phi) * Math.sin(theta);
                particles[idx+5] = r * Math.cos(phi);
            }
        };

        const setCubeTargets = () => {
            const dim = Math.ceil(Math.cbrt(PARTICLE_COUNT));
            const spacing = 40;
            const offset = (dim * spacing) / 2;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const x = i % dim;
                const y = Math.floor(i / dim) % dim;
                const z = Math.floor(i / (dim * dim));
                particles[idx+3] = x * spacing - offset;
                particles[idx+4] = y * spacing - offset;
                particles[idx+5] = z * spacing - offset;
            }
        };

        const setChaosTargets = () => {
             for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                particles[idx+3] = (Math.random() - 0.5) * 800;
                particles[idx+4] = (Math.random() - 0.5) * 600;
                particles[idx+5] = (Math.random() - 0.5) * 600;
             }
        };

        const updateTargets = () => {
             if (phase === 0) setCloudTargets();
             else if (phase === 1) setCubeTargets();
             else setChaosTargets();
        }
        setCloudTargets();

        // Render Loop
        const render = () => {
            time += 0.01;
            phaseTimer++;
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            // Camera
            const rotY = time * 0.3 + (mouseRef.current.x * 0.2);
            const rotX = Math.sin(time * 0.2) * 0.2 + (mouseRef.current.y * 0.2);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // Batches for drawing (Avoids 900 separate draw calls)
            const batches: number[][] = [[], [], [], []]; 

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP
                particles[idx] += (particles[idx+3] - particles[idx]) * TRANSITION_SPEED;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * TRANSITION_SPEED;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * TRANSITION_SPEED;

                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                // Noise in Chaos phase
                if (phase === 2) {
                    x += Math.sin(time * 3 + i) * 2;
                    y += Math.cos(time * 2 + i) * 2;
                }

                // Rotate
                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                let y1 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX;

                const scale = CAM_Z / (CAM_Z + z2);

                if (scale > 0) {
                    const px = cx + x1 * scale;
                    const py = cy + y1 * scale;
                    const size = particles[idx+7] * scale * (phase === 1 ? 2.5 : 2); 
                    const colorIdx = particles[idx+6];

                    // Push to appropriate color batch
                    batches[colorIdx].push(px, py, size);
                }
            }

            // Draw Batches
            for (let c = 0; c < 4; c++) {
                const batch = batches[c];
                if (batch.length === 0) continue;

                ctx.fillStyle = PALETTE[c];
                ctx.beginPath();
                for (let k = 0; k < batch.length; k += 3) {
                    // Use Rect for speed, resembles digital data
                    ctx.rect(batch[k] - batch[k+2]/2, batch[k+1] - batch[k+2]/2, batch[k+2], batch[k+2]);
                }
                ctx.fill();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
                updateTargets();
            }
        };
        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / width) * 2 - 1,
                y: ((e.clientY - rect.top) / height) * 2 - 1
            };
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

import React, { useState } from 'react';
import { useNavigation } from '../context/NavigationContext';
import { ChevronDown, Menu, X } from 'lucide-react';

interface NavItem {
  label: string;
  path: string;
}

interface NavSection {
  path: string;
  items?: NavItem[];
  children?: Record<string, NavSection>;
}

const SITEMAP: Record<string, NavSection> = {
  "Our Clients": {
    path: "our-clients",
    items: [
        { label: "Logistics", path: "our-clients/industries/logistics" },
        { label: "SMB Operations", path: "our-clients/industries/smb-operations" },
        { label: "Industrial Systems", path: "our-clients/industries/industrials" },
        { label: "Healthcare", path: "our-clients/industries/healthcare" },
        { label: "Natural Resources", path: "our-clients/industries/natural-resources" }
    ]
  },
  "Trust Center": {
    path: "trust-center"
  }
};

export const GlobalNav: React.FC = () => {
  const { navigateTo, currentPath } = useNavigation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);

  const handleNav = (path: string) => {
    navigateTo(path);
    setMobileMenuOpen(false);
    setActiveDropdown(null);
  };

  return (
    <nav className="fixed top-0 left-0 right-0 z-[100] bg-[#020202]/90 backdrop-blur-md border-b border-white/10 transition-all duration-300">
      <div className="max-w-7xl mx-auto px-6 h-32 md:h-44 flex items-center justify-between">
        {/* LOGO */}
        <button onClick={() => handleNav('platform')} className="flex items-center gap-3 group z-50">
          <img 
            src="https://uapriywlkpcpupdp.public.blob.vercel-storage.com/brand_logo_infogito.webp" 
            alt="Infogito Logo" 
            className="h-24 md:h-32 w-auto object-contain transition-transform duration-300 group-hover:scale-105" 
          />
        </button>

        {/* DESKTOP NAV */}
        <div className="hidden lg:flex items-center gap-8 text-sm font-medium text-white/60">
          {Object.entries(SITEMAP).map(([label, data]) => (
            <div 
                key={label} 
                className="relative group h-full flex items-center" 
                onMouseEnter={() => setActiveDropdown(label)} 
                onMouseLeave={() => setActiveDropdown(null)}
            >
              <button 
                onClick={() => handleNav(data.path)}
                className={`flex items-center gap-1 hover:text-white transition-colors py-8 ${currentPath.startsWith(data.path) ? 'text-[#69B7B2]' : ''}`}
              >
                {label}
                {(data.children || data.items) && (
                    <ChevronDown size={12} className={`transition-transform duration-300 ${activeDropdown === label ? 'rotate-180' : ''}`} />
                )}
              </button>

              {/* DROPDOWN */}
              {(data.children || data.items) && (
                <div 
                    className={`
                        absolute top-[80%] left-0 w-[240px] bg-[#0a0a0c] border border-white/10 rounded-xl shadow-2xl p-2 
                        transition-all duration-200 origin-top
                        flex flex-col gap-1
                        ${activeDropdown === label ? 'opacity-100 visible translate-y-0' : 'opacity-0 invisible translate-y-2'}
                    `}
                >
                  {/* Items */}
                  {data.items?.map(item => (
                      <button 
                        key={item.path} 
                        onClick={(e) => { e.stopPropagation(); handleNav(item.path); }} 
                        className="block w-full text-left text-white/60 hover:text-white text-xs hover:bg-white/5 p-3 rounded-lg transition-colors font-medium"
                      >
                          {item.label}
                      </button>
                  ))}
                </div>
              )}
            </div>
          ))}

          <button 
            onClick={() => handleNav('contact')} 
            className="px-6 py-2 rounded-full border border-white/10 hover:bg-white hover:text-black transition-all duration-300 hover:scale-105 active:scale-95"
          >
            Get In Touch
          </button>
        </div>

        {/* MOBILE TOGGLE */}
        <button 
            className="lg:hidden text-white/70 hover:text-white transition-colors p-2" 
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* MOBILE MENU OVERLAY */}
      <div className={`lg:hidden fixed inset-0 bg-[#020202] z-40 transition-transform duration-300 pt-36 px-6 overflow-y-auto ${mobileMenuOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="space-y-8 pb-12">
            {Object.entries(SITEMAP).map(([label, data]) => (
                <div key={label} className="border-b border-white/10 pb-6 animate-in slide-in-from-right-4 fade-in duration-500">
                    <button 
                        onClick={() => handleNav(data.path)} 
                        className="text-2xl font-serif text-white mb-4 block w-full text-left"
                    >
                        {label}
                    </button>

                    {data.items && (
                        <div className="pl-4 space-y-4 border-l border-white/10 ml-1">
                            {data.items.map(item => (
                                <button 
                                    key={item.path} 
                                    onClick={() => handleNav(item.path)} 
                                    className="block text-white/60 text-base hover:text-[#69B7B2] transition-colors text-left w-full"
                                >
                                    {item.label}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            ))}
            <button 
                onClick={() => handleNav('contact')} 
                className="w-full py-4 bg-[#69B7B2] text-black font-bold uppercase tracking-widest text-sm rounded-lg"
            >
                Get In Touch
            </button>
        </div>
      </div>
    </nav>
  );
};

import React from 'react';
import { NavigationProvider, useNavigation } from './context/NavigationContext';
import { GlobalNav } from './components/GlobalNav';

// Page Components
import { LandingPage } from './components/LandingPage'; // Serves as "Platform" now
import { CompliancePage } from './components/CompliancePage'; // Serves as Security & Privacy
import { SmallBusinessPage } from './components/SmallBusinessPage'; // Serves as SMB
import { GenericPage } from './components/GenericPage';
import { ContactPage } from './components/ContactPage';
import { OurWorkPage } from './components/OurWorkPage';
import { LogisticsPage } from './components/LogisticsPage';
import { HealthcarePage } from './components/HealthcarePage';
import { IndustrialsPage } from './components/IndustrialsPage';
import { NaturalResourcesPage } from './components/NaturalResourcesPage';
import { OurClientsPage } from './components/OurClientsPage'; 
import { CareersPage } from './components/CareersPage';
import { DownloadHeroesPage } from './components/DownloadHeroesPage';
import { TrustCenterPage } from './components/TrustCenterPage'; // Newly added

// Simple Home Redirector or Splash
const HomePage = () => {
    // Ideally this would be a high level intro, but for now we reuse GenericPage or redirect
    return (
        <GenericPage 
            title="Intelligence for the Real World." 
            subtitle="Infogito bridges the gap between complex enterprise data and actionable human insight." 
            category="Welcome" 
        />
    );
};

const MainContent = () => {
  const { currentPath } = useNavigation();

  // ROUTING LOGIC

  // 1. TOP LEVEL PAGES
  if (currentPath === 'contact') return <ContactPage />;
  if (currentPath === 'our-clients') return <OurClientsPage />; 
  if (currentPath === 'about/careers') return <CareersPage />;
  if (currentPath === 'download-heroes') return <DownloadHeroesPage />;
  if (currentPath === 'trust-center') return <TrustCenterPage />; // New Route

  // 2. EXACT MATCHES FOR EXISTING COMPLEX PAGES
  if (currentPath === 'platform' || currentPath === 'home') {
      return <LandingPage />;
  }
  if (currentPath === 'platform/features/security-and-privacy') {
      return <CompliancePage />;
  }
  if (currentPath === 'our-clients/industries/smb-operations') {
      return <SmallBusinessPage />;
  }
  if (currentPath === 'our-clients/industries/logistics') {
      return <LogisticsPage />;
  }
  if (currentPath === 'our-clients/industries/healthcare') {
      return <HealthcarePage />;
  }
  if (currentPath === 'our-clients/industries/industrials') {
      return <IndustrialsPage />;
  }
  if (currentPath === 'our-clients/industries/natural-resources') {
      return <NaturalResourcesPage />;
  }

  if (currentPath === 'platform/features/agentic-workflows') {
      return <GenericPage title="Agentic Workflows" subtitle="Build complex autonomous agents visually." category="Platform Feature" />;
  }

  // 3. SECTION ROOTS
  if (currentPath.startsWith('our-work')) {
      return <OurWorkPage />;
  }

  // 4. PATTERN MATCHING FOR GENERIC PAGES (Catch-all for subpages not explicitly handled)

  // INDUSTRIES
  if (currentPath.startsWith('our-clients/industries/')) {
      const industry = currentPath.split('/').pop()?.replace(/-/g, ' ');
      return <GenericPage title={industry || "Industry"} subtitle="Tailored AI solutions for your specific sector requirements." category="Industry Solution" />;
  }

  // FEATURES
  if (currentPath.startsWith('platform/features/')) {
      const feature = currentPath.split('/').pop()?.replace(/-/g, ' ');
      return <GenericPage title={feature || "Feature"} subtitle="Powerful capabilities built into the core of the Infogito platform." category="Platform Feature" />;
  }

  // Default / 404 Fallback to Home
  return <HomePage />;
};

const App: React.FC = () => {
  return (
    <NavigationProvider>
      <GlobalNav />
      {/* Spacer for increased header height */}
      <div className="pt-8 md:pt-20">
        <MainContent />
      </div>
    </NavigationProvider>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';

export const LogisticsHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        // Alpha: false for performance (no composition with background)
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        // --- CONFIG ---
        const COLS = 50; 
        const ROWS = 24;
        const PARTICLE_COUNT = COLS * ROWS; 
        const CAM_Z = 1200;

        // Slower transitions for smoother feel
        const PHASE_DURATION = 800; // Increased from 600
        const TRANSITION_SPEED = 0.025; // Decreased from 0.04

        // --- STATE & BUFFERS ---
        // Layout: [x, y, z, tx, ty, tz, colorType]
        const P_STRIDE = 7;
        const data = new Float32Array(PARTICLE_COUNT * P_STRIDE);

        // Project buffers (Allocated ONCE to avoid GC)
        const projX = new Float32Array(PARTICLE_COUNT);
        const projY = new Float32Array(PARTICLE_COUNT);
        const projScale = new Float32Array(PARTICLE_COUNT);

        // Initialize state
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            data[idx] = (Math.random() - 0.5) * 2000;
            data[idx+1] = (Math.random() - 0.5) * 2000;
            data[idx+2] = (Math.random() - 0.5) * 2000;

            // Color: 0=Cyan, 1=Amber, 2=White
            const rand = Math.random();
            data[idx+6] = rand > 0.9 ? 1 : (rand > 0.7 ? 2 : 0);
        }

        let phase = 0; 
        let phaseTimer = 0;

        // --- GEOMETRY GENERATORS ---
        const setTargetPlane = () => {
            const spacingX = 35;
            const spacingY = 35;
            const offsetX = (COLS * spacingX) / 2;
            const offsetY = (ROWS * spacingY) / 2;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                data[idx+3] = col * spacingX - offsetX;
                data[idx+4] = row * spacingY - offsetY;
                data[idx+5] = Math.sin(col * 0.2) * 40 + Math.cos(row * 0.2) * 40;
            }
        };

        const setTargetSphere = () => {
            const radius = 300;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const lat = (row / (ROWS - 1)) * Math.PI - Math.PI / 2;
                const lon = (col / (COLS - 1)) * Math.PI * 2;
                data[idx+3] = radius * Math.cos(lat) * Math.cos(lon);
                data[idx+4] = radius * Math.sin(lat);
                data[idx+5] = radius * Math.cos(lat) * Math.sin(lon);
            }
        };

        const setTargetTorus = () => {
            const R = 260; const r = 90;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const u = (col / COLS) * Math.PI * 2;
                const v = (row / ROWS) * Math.PI * 2;
                data[idx+3] = (R + r * Math.cos(v)) * Math.cos(u);
                data[idx+4] = (R + r * Math.cos(v)) * Math.sin(u);
                data[idx+5] = r * Math.sin(v);
            }
        };

        const updateTargets = () => {
            if (phase === 0) setTargetPlane();
            else if (phase === 1) setTargetSphere();
            else setTargetTorus();
        };
        setTargetPlane();

        // --- RENDER LOOP ---
        const render = () => {
            time += 0.015;
            phaseTimer++;
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            // Camera Matrices
            const rotY = time * 0.2;
            const rotX = Math.sin(time * 0.15) * 0.2;
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // 1. UPDATE & PROJECT
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP
                const tx = data[idx+3], ty = data[idx+4], tz = data[idx+5];
                data[idx] += (tx - data[idx]) * TRANSITION_SPEED;
                data[idx+1] += (ty - data[idx+1]) * TRANSITION_SPEED;
                data[idx+2] += (tz - data[idx+2]) * TRANSITION_SPEED;

                let x = data[idx];
                let y = data[idx+1];
                let z = data[idx+2];

                // Wave effect (only phase 0)
                if (phase === 0) z += Math.sin(x * 0.03 + time * 4) * 20;

                // 3D Rotation
                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                let y1 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX;

                const scale = CAM_Z / (CAM_Z + z2);
                projScale[i] = scale;

                if (scale > 0) {
                    projX[i] = cx + x1 * scale;
                    projY[i] = cy + y1 * scale;
                }
            }

            // 2. DRAW CONNECTIONS (Single Batch Path)
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(6, 182, 212, 0.12)'; // Cyan lines
            ctx.lineWidth = 0.8; 

            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const i = r * COLS + c;
                    if (projScale[i] <= 0) continue;

                    // Right Neighbor
                    if (c < COLS - 1) {
                        const right = i + 1;
                        if (projScale[right] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[right], projY[right]);
                        }
                    }
                    // Down Neighbor
                    if (r < ROWS - 1) {
                        const down = i + COLS;
                        if (projScale[down] > 0) {
                            ctx.moveTo(projX[i], projY[i]);
                            ctx.lineTo(projX[down], projY[down]);
                        }
                    }
                }
            }
            ctx.stroke();

            // 3. DRAW NODES (Batch By Color)
            // Function to draw all nodes of a specific color type
            const drawBatch = (color: string, typeVal: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                for (let i = 0; i < PARTICLE_COUNT; i++) {
                    // Fast check for color type
                    if (Math.abs(data[i * P_STRIDE + 6] - typeVal) > 0.1) continue;
                    if (projScale[i] <= 0) continue;

                    const size = (1.5 + Math.sin(time * 5 + i) * 0.5) * projScale[i];
                    ctx.rect(projX[i] - size/2, projY[i] - size/2, size, size);
                }
                ctx.fill();
            };

            drawBatch('#06b6d4', 0); // Cyan
            drawBatch('#f59e0b', 1); // Amber
            drawBatch('#ffffff', 2); // White

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.parentElement.getBoundingClientRect();
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
                updateTargets();
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        const PARTICLE_COUNT = 900; 
        const CAM_Z = 1000;
        const P_STRIDE = 8;
        const particles = new Float32Array(PARTICLE_COUNT * P_STRIDE);

        // Colors: Violet, Blue, Cyan, White
        const PALETTE = ['#8b5cf6', '#3b82f6', '#22d3ee', '#ffffff'];

        // Init
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            particles[idx] = (Math.random()-0.5) * 500;
            particles[idx+1] = (Math.random()-0.5) * 500;
            particles[idx+2] = (Math.random()-0.5) * 500;
            particles[idx+6] = Math.floor(Math.random() * 4); // Color Index
            particles[idx+7] = 0.5 + Math.random(); // Size
        }

        let phase = 0; 
        let phaseTimer = 0;

        // Smoother, Slower Transition
        const PHASE_DURATION = 600; // Increased from 450
        const TRANSITION_SPEED = 0.025; // Decreased from 0.04

        // Generators
        const setCloudTargets = () => {
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const r = 250 + Math.random() * 100;
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos((Math.random() * 2) - 1);

                particles[idx+3] = r * Math.sin(phi) * Math.cos(theta);
                particles[idx+4] = r * Math.sin(phi) * Math.sin(theta);
                particles[idx+5] = r * Math.cos(phi);
            }
        };

        const setCubeTargets = () => {
            const dim = Math.ceil(Math.cbrt(PARTICLE_COUNT));
            const spacing = 40;
            const offset = (dim * spacing) / 2;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const x = i % dim;
                const y = Math.floor(i / dim) % dim;
                const z = Math.floor(i / (dim * dim));
                particles[idx+3] = x * spacing - offset;
                particles[idx+4] = y * spacing - offset;
                particles[idx+5] = z * spacing - offset;
            }
        };

        const setChaosTargets = () => {
             for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                particles[idx+3] = (Math.random() - 0.5) * 800;
                particles[idx+4] = (Math.random() - 0.5) * 600;
                particles[idx+5] = (Math.random() - 0.5) * 600;
             }
        };

        const updateTargets = () => {
             if (phase === 0) setCloudTargets();
             else if (phase === 1) setCubeTargets();
             else setChaosTargets();
        }
        setCloudTargets();

        // Render Loop
        const render = () => {
            time += 0.01;
            phaseTimer++;
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            // Camera
            const rotY = time * 0.3 + (mouseRef.current.x * 0.2);
            const rotX = Math.sin(time * 0.2) * 0.2 + (mouseRef.current.y * 0.2);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            // Batches for drawing (Avoids 900 separate draw calls)
            const batches: number[][] = [[], [], [], []]; 

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;

                // LERP
                particles[idx] += (particles[idx+3] - particles[idx]) * TRANSITION_SPEED;
                particles[idx+1] += (particles[idx+4] - particles[idx+1]) * TRANSITION_SPEED;
                particles[idx+2] += (particles[idx+5] - particles[idx+2]) * TRANSITION_SPEED;

                let x = particles[idx];
                let y = particles[idx+1];
                let z = particles[idx+2];

                // Noise in Chaos phase
                if (phase === 2) {
                    x += Math.sin(time * 3 + i) * 2;
                    y += Math.cos(time * 2 + i) * 2;
                }

                // Rotate
                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                let y1 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX;

                const scale = CAM_Z / (CAM_Z + z2);

                if (scale > 0) {
                    const px = cx + x1 * scale;
                    const py = cy + y1 * scale;
                    const size = particles[idx+7] * scale * (phase === 1 ? 2.5 : 2); 
                    const colorIdx = particles[idx+6];

                    // Push to appropriate color batch
                    batches[colorIdx].push(px, py, size);
                }
            }

            // Draw Batches
            for (let c = 0; c < 4; c++) {
                const batch = batches[c];
                if (batch.length === 0) continue;

                ctx.fillStyle = PALETTE[c];
                ctx.beginPath();
                for (let k = 0; k < batch.length; k += 3) {
                    // Use Rect for speed, resembles digital data
                    ctx.rect(batch[k] - batch[k+2]/2, batch[k+1] - batch[k+2]/2, batch[k+2], batch[k+2]);
                }
                ctx.fill();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const rect = canvas.parentElement.getBoundingClientRect();
                const dpr = window.devicePixelRatio || 1;
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
                updateTargets();
            }
        };
        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / width) * 2 - 1,
                y: ((e.clientY - rect.top) / height) * 2 - 1
            };
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

import React, { useState } from 'react';
import { useNavigation } from '../context/NavigationContext';
