                    </button>

                    {data.items && (
                        <div className="pl-4 space-y-4 border-l border-white/10 ml-1">
                            {data.items.map(item => (
                                <button 
                                    key={item.path} 
                                    onClick={() => handleNav(item.path)} 
                                    className="block text-white/60 text-base hover:text-[#69B7B2] transition-colors text-left w-full"
                                >
                                    {item.label}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            ))}
            <button 
                onClick={() => handleNav('contact')} 
                className="w-full py-4 bg-[#69B7B2] text-black font-bold uppercase tracking-widest text-sm rounded-lg"
            >
                Get In Touch
            </button>
        </div>
      </div>
    </nav>
  );
};

import React, { useEffect, useRef } from 'react';

export const ContactHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width;
        let h = canvas.height;
        let frameId: number;
        let time = 0;

        // --- CONFIGURATION ---
        const SHEET_W = 200;
        const SHEET_H = 280;
        const GRID_RES = 12; // Grid density for folding
        const INK_LINES = 12;
        const CHARS_PER_LINE = 20;

        // --- DATA STRUCTURES ---

        // 1. PAPER MESH (Grid of points)
        // We track UVs to handle folding logic
        const paperNodes: {u: number, v: number, x: number, y: number, z: number}[] = [];
        for(let y=0; y<=GRID_RES; y++) {
            for(let x=0; x<=GRID_RES; x++) {
                paperNodes.push({
                    u: x/GRID_RES,
                    v: y/GRID_RES,
                    x: 0, y: 0, z: 0
                });
            }
        }

        // 2. INK PARTICLES
        // Attached to UV space initially, then detach
        const inkParticles: {u: number, v: number, x: number, y: number, z: number, detached: boolean, dx: number, dy: number, dz: number}[] = [];
        for(let l=0; l<INK_LINES; l++) {
            const lineY = 0.15 + (l / INK_LINES) * 0.7;
            for(let c=0; c<CHARS_PER_LINE; c++) {
                if (Math.random() > 0.8) continue; // Random spaces
                const charX = 0.15 + (c / CHARS_PER_LINE) * 0.7 + (Math.random()-0.5)*0.01;
                inkParticles.push({
                    u: charX,
                    v: lineY,
                    x: 0, y: 0, z: 0,
                    detached: false,
                    dx: 0, dy: 0, dz: 0
                });
            }
        }

        // --- STATE MACHINE ---
        // 0: FLIGHT (Plane moving)
        // 1: LANDING (Plane stopping)
        // 2: UNFOLD (Morph to Sheet)
        // 3: UNWRITE (Ink lifts off)
        // 4: RESET (Fade out)
        let phase = 0;
        let phaseTimer = 0;
        let globalZ = 0; // Movement of the whole object

        // --- TRANSFORM FUNCTIONS ---

        // Maps UV (0-1) to 3D Paper Plane shape
        const getPlanePosition = (u: number, v: number, out: {x:number, y:number, z:number}) => {
            // Fold logic: 
            // Center spine is u=0.5
            // Wings fold up/out
            const foldAngle = Math.PI * 0.45; 
            const center = 0.5;
            const distFromCenter = Math.abs(u - center) * SHEET_W;
            const isLeft = u < center;

            // Base Plane coords
            let x = distFromCenter * Math.cos(foldAngle) * (isLeft ? -1 : 1);
            let y = distFromCenter * Math.sin(foldAngle); // Wings go up
            let z = (v - 0.5) * SHEET_H;

            // Dart shape taper
            // Reduce width at nose (v=0)
            const taper = 0.2 + 0.8 * v; // Nose is narrow
            x *= taper;
            y *= taper;

            out.x = x; 
            out.y = y; 
            out.z = z;
        };

        // Maps UV (0-1) to Flat Sheet
        const getSheetPosition = (u: number, v: number, out: {x:number, y:number, z:number}) => {
            out.x = (u - 0.5) * SHEET_W;
            out.y = (v - 0.5) * SHEET_H; // Vertical sheet
            out.z = 0;
        };

        const render = () => {
            time += 0.01;
            phaseTimer++;

            // Phase Switching
            if (phase === 0 && phaseTimer > 200) { phase = 1; phaseTimer = 0; } // Fly -> Land
            if (phase === 1 && phaseTimer > 60) { phase = 2; phaseTimer = 0; } // Land -> Unfold
            if (phase === 2 && phaseTimer > 120) { phase = 3; phaseTimer = 0; } // Unfold -> Unwrite
            if (phase === 3 && phaseTimer > 250) { phase = 4; phaseTimer = 0; } // Unwrite -> Reset
            if (phase === 4 && phaseTimer > 60) { phase = 0; phaseTimer = 0; globalZ = -800; } // Reset -> Fly

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const cx = w > 1024 ? w * 0.75 : w * 0.5;
            const cy = h * 0.5;

            // --- ANIMATION LOGIC ---

            let morphFactor = 0; // 0 = Plane, 1 = Sheet
            let globalRotX = 0;
            let globalRotY = 0;
            let globalRotZ = 0;

            if (phase === 0) { // FLYING
                morphFactor = 0;
                globalZ += 6; // Fly forward
                globalRotZ = Math.sin(time * 2) * 0.1; // Bank
                globalRotX = -Math.PI / 2; // Face forward
            } else if (phase === 1) { // LANDING
                morphFactor = 0;
                // Slow down rotation to face camera flat
                const t = phaseTimer / 60;
                // Smooth step to orient for unfolding
                globalRotX = -Math.PI/2 * (1-t); 
                globalRotZ = 0;
            } else if (phase === 2) { // UNFOLDING
                const t = Math.min(1, phaseTimer / 100);
                // Ease out elastic
                morphFactor = t;
            } else if (phase === 3) { // UNWRITING
                morphFactor = 1;
            } else { // RESET
                morphFactor = 1 - (phaseTimer / 60); // Quick fold back?
                globalZ -= 20; // Fly away backward
            }

            const planePos = {x:0, y:0, z:0};
            const sheetPos = {x:0, y:0, z:0};

            // --- UPDATE & DRAW PAPER ---
            ctx.strokeStyle = `rgba(105, 183, 178, ${0.3})`;
            ctx.lineWidth = 1;
            ctx.beginPath();

            // Draw as grid lines
            for(let i=0; i<paperNodes.length; i++) {
                const n = paperNodes[i];
                getPlanePosition(n.u, n.v, planePos);
                getSheetPosition(n.u, n.v, sheetPos);

                // Lerp
                let x = planePos.x + (sheetPos.x - planePos.x) * morphFactor;
                let y = planePos.y + (sheetPos.y - planePos.y) * morphFactor;
                let z = planePos.z + (sheetPos.z - planePos.z) * morphFactor;

                // Global Transform
                // Rotate
                const grx = globalRotX;
                let y1 = y * Math.cos(grx) - z * Math.sin(grx);
                let z1 = z * Math.cos(grx) + y * Math.sin(grx);
                y = y1; z = z1;

                let x1 = x * Math.cos(globalRotZ) - y * Math.sin(globalRotZ);
                let y2 = y * Math.cos(globalRotZ) + x * Math.sin(globalRotZ);
                x = x1; y = y2;

                z += globalZ + 400; // Camera offset

                // Project
                const scale = 800 / (800 + z);
                const px = cx + x * scale;
                const py = cy + y * scale;

                n.x = px; n.y = py; n.z = z; // Store projected for lines

                // Draw dots at nodes
                if (z > -700) {
                    ctx.fillStyle = `rgba(105, 183, 178, ${0.5 * morphFactor + 0.1})`;
                    ctx.fillRect(px, py, 1.5, 1.5);
                }
            }

            // Connect Grid
            for(let y=0; y<GRID_RES; y++) {
                for(let x=0; x<GRID_RES; x++) {
                    const i = y * (GRID_RES+1) + x;
                    const right = i + 1;
                    const down = i + (GRID_RES+1);

                    const p1 = paperNodes[i];
                    if (p1.z < -700) continue;

                    const pRight = paperNodes[right];
                    const pDown = paperNodes[down];

                    if (x < GRID_RES) {
                        ctx.moveTo(p1.x, p1.y);
                        ctx.lineTo(pRight.x, pRight.y);
                    }
                    if (y < GRID_RES) {
                        ctx.moveTo(p1.x, p1.y);
                        ctx.lineTo(pDown.x, pDown.y);
                    }
                }
            }
            ctx.stroke();

            // --- UPDATE & DRAW INK ---
            ctx.fillStyle = '#fbbf24'; // Amber

            for(let i=0; i<inkParticles.length; i++) {
                const p = inkParticles[i];

                // Base Position (Same interpolation as paper)
                getPlanePosition(p.u, p.v, planePos);
                getSheetPosition(p.u, p.v, sheetPos);

                let x = planePos.x + (sheetPos.x - planePos.x) * morphFactor;
                let y = planePos.y + (sheetPos.y - planePos.y) * morphFactor;
                let z = planePos.z + (sheetPos.z - planePos.z) * morphFactor;

                // UNWRITING LOGIC
                if (phase === 3) {
                    // Detach logic
                    if (!p.detached) {
                        // Start detaching based on time + random variance
                        if (Math.random() < 0.05) {
                            p.detached = true;
                            p.dx = (Math.random()-0.5) * 2;
                            p.dy = -(Math.random() * 2 + 1); // Float UP
                            p.dz = (Math.random()-0.5) * 5;
                        }
                    }
                } else if (phase === 4 || phase === 0) {
                    p.detached = false;
                    p.dx = 0; p.dy = 0; p.dz = 0;
                }

                if (p.detached) {
                    // Add noise movement
                    x += p.dx * phaseTimer * 0.1 + Math.sin(time * 5 + i) * 5;
                    y += p.dy * phaseTimer * 0.1;
                    z += p.dz * phaseTimer * 0.1 + 50; // Lift off surface
                }

                // Global Transform (Same as Paper)
                const grx = globalRotX;
                let y1 = y * Math.cos(grx) - z * Math.sin(grx);
                let z1 = z * Math.cos(grx) + y * Math.sin(grx);
                y = y1; z = z1;

                let x1 = x * Math.cos(globalRotZ) - y * Math.sin(globalRotZ);
                let y2 = y * Math.cos(globalRotZ) + x * Math.sin(globalRotZ);
                x = x1; y = y2;

                z += globalZ + 400;

                // Project
                const scale = 800 / (800 + z);
                const px = cx + x * scale;
                const py = cy + y * scale;

                if (scale > 0 && z > -700) {
                    // Fade out as they float away
                    let alpha = 1;
                    if (p.detached) alpha = Math.max(0, 1 - (phaseTimer / 200));

                    ctx.globalAlpha = alpha;
                    const size = p.detached ? 2 * scale : 1.5 * scale;
                    ctx.beginPath();
                    ctx.arc(px, py, size, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.globalAlpha = 1;

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full mix-blend-screen opacity-90" />;
};

import React, { useEffect, useRef } from 'react';

export const ClientsHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let w = canvas.width;
        let h = canvas.height;
        let frameId: number;
        let time = 0;

        // --- CONFIG ---
        const CAM_Z = 1200;
        const SCALE = 350;

        // Icosahedron Vertices (Golden Ratio)
        const t = (1.0 + Math.sqrt(5.0)) / 2.0;
        const rawVerts = [
            [-1,  t,  0], [ 1,  t,  0], [-1, -t,  0], [ 1, -t,  0],
            [ 0, -1,  t], [ 0,  1,  t], [ 0, -1, -t], [ 0,  1, -t],
            [ t,  0, -1], [ t,  0,  1], [-t,  0, -1], [-t,  0,  1]
        ];

        // Connections (Indices)
        const edges = [
            [0, 11], [0, 5], [0, 1], [0, 7], [0, 10],
            [1, 0], [1, 5], [1, 9], [1, 8], [1, 7],
            [2, 3], [2, 4], [2, 11], [2, 10], [2, 6],
            [3, 2], [3, 4], [3, 9], [3, 8], [3, 6],
            [4, 2], [4, 3], [4, 9], [4, 5], [4, 11],
            [5, 0], [5, 1], [5, 9], [5, 4], [5, 11],
            [6, 2], [6, 3], [6, 8], [6, 7], [6, 10],
            [7, 0], [7, 1], [7, 8], [7, 6], [7, 10],
            [8, 1], [8, 3], [8, 6], [8, 7], [8, 9],
            [9, 1], [9, 3], [9, 4], [9, 5], [9, 8],
            [10, 0], [10, 2], [10, 6], [10, 7], [10, 11],
            [11, 0], [11, 2], [11, 4], [11, 5], [11, 10]
        ];

        // Normalize vertices
        const nodes = rawVerts.map(v => {
            const len = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]);
            return { x: v[0]/len * SCALE, y: v[1]/len * SCALE, z: v[2]/len * SCALE };
        });

        // Add sub-nodes on edges for complexity
        const subNodes: {x:number, y:number, z:number}[] = [];
        edges.forEach(e => {
            const n1 = nodes[e[0]];
            const n2 = nodes[e[1]];
            // Midpoint
            subNodes.push({
                x: (n1.x + n2.x) / 2,
                y: (n1.y + n2.y) / 2,
                z: (n1.z + n2.z) / 2
            });
        });

        const render = () => {
            time += 0.005; // Slow, stable rotation

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const cx = w > 1024 ? w * 0.75 : w * 0.5;
            const cy = h * 0.5;

            // Rotation
            const rotY = time;
            const rotX = Math.sin(time * 0.5) * 0.2;

            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            const project = (p: {x:number, y:number, z:number}) => {
                let x = p.x * cosY - p.z * sinY;
                let z = p.z * cosY + p.x * sinY;
                let y = p.y * cosX - z * sinX;
                z = z * cosX + p.y * sinX;
                const scale = CAM_Z / (CAM_Z + z);
                return { x: cx + x * scale, y: cy + y * scale, z, scale };
            };

            const projNodes = nodes.map(project);
            const projSub = subNodes.map(project);

            // Draw Core Structure (Background Faces? No, wireframe is cleaner)

            // 1. Draw Edges (Heavy)
            ctx.lineWidth = 2;
            edges.forEach(e => {
                const p1 = projNodes[e[0]];
                const p2 = projNodes[e[1]];

                if (p1.z > -500 && p2.z > -500) {
                    const depth = (p1.scale + p2.scale) / 2;
                    ctx.strokeStyle = `rgba(105, 183, 178, ${0.1 * depth})`;
                    ctx.beginPath();
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            });

            // 2. Draw Sub-Nodes (Data points)
            projSub.forEach(p => {
                if (p.z > -500) {
                    const size = 1.5 * p.scale;
                    ctx.fillStyle = `rgba(255, 255, 255, ${0.3 * p.scale})`;
                    ctx.beginPath(); ctx.arc(p.x, p.y, size, 0, Math.PI*2); ctx.fill();
                }
            });

            // 3. Draw Main Nodes (Hubs)
            projNodes.forEach((p, i) => {
                if (p.z > -500) {
                    // Pulse
                    const pulse = Math.sin(time * 5 + i) * 0.2 + 1;
                    const size = 6 * p.scale * pulse;

                    // Glow
                    ctx.fillStyle = 'rgba(105, 183, 178, 0.2)';
                    ctx.beginPath(); ctx.arc(p.x, p.y, size * 2, 0, Math.PI*2); ctx.fill();

                    // Core
                    ctx.fillStyle = '#69B7B2';
                    ctx.beginPath(); ctx.arc(p.x, p.y, size * 0.5, 0, Math.PI*2); ctx.fill();

                    // Label (Abstract ID)
                    if (p.scale > 0.8) {
                        ctx.fillStyle = `rgba(255,255,255,${(p.scale-0.8)*2})`;
                        ctx.font = '8px monospace';
                        ctx.fillText(`NODE_${i.toString().padStart(2,'0')}`, p.x + 10, p.y);
                    }
                }
            });

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full mix-blend-screen" />;
};

import React, { useEffect, useRef } from 'react';

const ContactHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = canvas.width;
        let height = canvas.height;
        let cx = width / 2;
        let cy = height / 2;

        let frameId: number;
        let isVisible = true;

        // --- 3D ENGINE SETTINGS ---
        const FL = 800;
        let mouseX = 0;
        let mouseY = 0;
        let targetRotX = 0;
        let targetRotY = 0;

        // --- ANIMATION STATE ---
        let phase = 0; 
        let phaseTimer = 0;
        let globalTime = 0;
        let loopSeed = 0; 
        let meshOpacity = 0; 

        // --- GEOMETRY DATA STRUCTURES ---
        const SHEET_SIZE = 150; 

        const createVec = (x: number, y: number, z: number) => ({ x, y, z });

        const flatVerts = [
            createVec(-SHEET_SIZE, -SHEET_SIZE * 1.4, 0), createVec(0, -SHEET_SIZE * 1.4, 0), createVec(SHEET_SIZE, -SHEET_SIZE * 1.4, 0),
            createVec(-SHEET_SIZE, 0, 0),                 createVec(0, 0, 0),                 createVec(SHEET_SIZE, 0, 0),
            createVec(-SHEET_SIZE, SHEET_SIZE * 1.4, 0),  createVec(0, SHEET_SIZE * 1.4, 0),  createVec(SHEET_SIZE, SHEET_SIZE * 1.4, 0)
        ];

        const planeVerts = [
            createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),
            createVec(-SHEET_SIZE * 1.2, SHEET_SIZE, 20), createVec(0, -SHEET_SIZE * 0.5, -50), createVec(SHEET_SIZE * 1.2, SHEET_SIZE, 20),
            createVec(-20, SHEET_SIZE * 1.4, 0),     createVec(0, SHEET_SIZE * 1.4, 0),      createVec(20, SHEET_SIZE * 1.4, 0)
        ];

        const currentVerts = flatVerts.map(v => ({...v}));
        const worldVertsBuffer = flatVerts.map(() => ({ x: 0, y: 0, z: 0, px: 0, py: 0, scale: 0 }));

        const planePos = { x: 0, y: 0, z: 0 };
        const planeVel = { x: 0, y: 0, z: 0 };
        const planeRot = { x: 0, y: 0, z: 0 };

        // --- PARTICLES ---
        const MAX_PARTICLES = 60;
        const particles = Array.from({ length: MAX_PARTICLES }, () => ({
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            life: 0,
            color: '#fff',
            type: 'ember' as 'data' | 'trail' | 'ember',
            active: false
        }));

        const lerp = (start: number, end: number, t: number) => start + (end - start) * t;

        const spawnParticle = (type: 'data' | 'trail' | 'ember', ox: number, oy: number, oz: number, spread: number) => {
            for (let i = 0; i < MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) {
                    p.active = true;
                    p.x = ox + (Math.random() - 0.5) * spread;
                    p.y = oy + (Math.random() - 0.5) * spread;
                    p.z = oz + (Math.random() - 0.5) * spread;
                    p.vx = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vy = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vz = type === 'trail' ? 10 : (Math.random() - 0.5) * 5;
                    p.life = 1.0;
                    p.color = type === 'data' ? '#69B7B2' : type === 'ember' ? '#f59e0b' : '#ffffff';
                    p.type = type;
                    break; 
                }
            }
        };

        const render = () => {
            frameId = requestAnimationFrame(render);
            if (!isVisible) return;

            globalTime += 0.016;

            ctx.fillStyle = 'rgba(2, 2, 2, 0.25)';
            ctx.fillRect(0, 0, width, height);

            targetRotY += (mouseX * 0.1 - targetRotY) * 0.05;
            targetRotX += (mouseY * 0.1 - targetRotX) * 0.05;

            const cosY = Math.cos(targetRotX);
            const sinY = Math.sin(targetRotX);
            const cosX = Math.cos(targetRotY); 
            const sinX = Math.sin(targetRotY);

            // --- PHASE LOGIC ---
            if (phase === 0) { // COALESCE
                phaseTimer += 0.006;
                meshOpacity = Math.min(1, phaseTimer);
                const t = Math.min(1, phaseTimer / 2.0);
                const ease = 1 - Math.pow(1 - t, 4); 

                for(let i=0; i<9; i++) {
                    const float = Math.sin(globalTime * 2 + i) * 20 * (1-ease);
                    const idx = i * 1.0;
                    const noiseX = Math.sin(idx * 12.3 + loopSeed) * 1200 + float;
                    const noiseY = Math.cos(idx * 45.6 + loopSeed) * 800 + float;
                    const noiseZ = Math.sin(idx * 78.9 + loopSeed) * 1000 - 500;

                    const cv = currentVerts[i];
                    const fv = flatVerts[i];
                    cv.x = lerp(noiseX, fv.x, ease);
                    cv.y = lerp(noiseY, fv.y, ease);
                    cv.z = lerp(noiseZ, fv.z, ease);
                }

                if (Math.random() > 0.85 && phaseTimer < 1.5) spawnParticle('data', 0, 0, 0, 800);
                if (phaseTimer > 2.5) { phase = 1; phaseTimer = 0; meshOpacity = 1; }
            }
            else if (phase === 1) { // FOLD
                phaseTimer += 0.01;
                const t = Math.min(1, phaseTimer);
                const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

                for(let i=0; i<9; i++) {
                    currentVerts[i].x = lerp(flatVerts[i].x, planeVerts[i].x, ease);
                    currentVerts[i].y = lerp(flatVerts[i].y, planeVerts[i].y, ease);
                    currentVerts[i].z = lerp(flatVerts[i].z, planeVerts[i].z, ease);
                }

                if (t > 0.8) {
                    cx = width/2 + (Math.random()-0.5)*5;
                    cy = height/2 + (Math.random()-0.5)*5;
                } else {
                    cx = width/2; cy = height/2;
                }

                if (phaseTimer > 1.2) { 
                    phase = 2; phaseTimer = 0;
                    planePos.x = 0; planePos.y = 0; planePos.z = 0;
                    planeRot.x = 0; planeRot.y = 0; planeRot.z = 0;

                    const angle = (Math.random() - 0.5) * 2.5;
                    const lift = (Math.random() - 0.5) * 1.0;
                    planeVel.x = Math.sin(angle) * 8;
                    planeVel.y = Math.sin(lift) * 6;
                    planeVel.z = 18;
                }
            }
            else if (phase === 2) { // FLIGHT
                phaseTimer += 0.016;
                planeVel.z += 0.2; 
                planePos.x += planeVel.x;
                planePos.y += planeVel.y;
                planePos.z += planeVel.z;

                const targetBank = planeVel.x * 0.03;
                planeRot.z += (targetBank - planeRot.z) * 0.1;
                const targetPitch = planeVel.y * 0.03;
                planeRot.x += (targetPitch - planeRot.x) * 0.1;
                planeRot.y += planeVel.x * 0.002;

                if (planePos.z > 2000) meshOpacity = Math.max(0, 1 - ((planePos.z - 2000) / 1500));

                if(Math.random() > 0.5) spawnParticle('ember', planePos.x, planePos.y, planePos.z, 10);
                if(Math.random() > 0.8) spawnParticle('trail', planePos.x, planePos.y, planePos.z, 20);

                if (planePos.z > 5000) { 
                    phase = 3; 
                    phaseTimer = 0; 
                }
            }
            else if (phase === 3) { // RESET
                loopSeed += 13.7;
                meshOpacity = 0;
                phase = 0;
                cx = width/2; cy = height/2;

                planePos.x = 0; planePos.y = 0; planePos.z = 0;
                planeRot.x = 0; planeRot.y = 0; planeRot.z = 0;
                planeVel.x = 0; planeVel.y = 0; planeVel.z = 0;
            }

            // --- TRANSFORM & PROJECT (BATCHED) ---
            for(let i=0; i<9; i++) {
                const v = currentVerts[i];
                let x = v.x + planePos.x;
                let y = v.y + planePos.y;
                let z = v.z + planePos.z;

                if (phase === 2) {
                    const cosRY = Math.cos(planeRot.y); const sinRY = Math.sin(planeRot.y);
                    const cosRX = Math.cos(planeRot.x); const sinRX = Math.sin(planeRot.x);

                    let tx = x * cosRY - z * sinRY;
                    let tz = z * cosRY + x * sinRY;
                    x = tx; z = tz;
                    let ty = y * cosRX - z * sinRX;
                    let tz2 = z * cosRX + y * sinRX;
                    y = ty; z = tz2;
                }

                let y1 = y * cosY - z * sinY;
                let z1 = z * cosY + y * sinY;
                let x1 = x * cosX - z1 * sinX;
                let z2 = z1 * cosX + x * sinX;

                const scale = FL / (FL + z2);
                const buff = worldVertsBuffer[i];
                buff.x = x1; buff.y = y1; buff.z = z2;
                buff.px = cx + x1 * scale;
                buff.py = cy + y1 * scale;
                buff.scale = scale;
            }

            if (meshOpacity > 0.01) {
                const accentFill = phase === 2 ? `rgba(105,183,178,${meshOpacity * 0.2})` : `rgba(255,255,255,${meshOpacity * 0.1})`;
                const baseFill = `rgba(255,255,255,${meshOpacity * 0.05})`;

                ctx.lineWidth = 1;
                ctx.strokeStyle = `rgba(255,255,255,${0.1 * meshOpacity})`;

                const addTri = (i1: number, i2: number, i3: number) => {
                    const p1 = worldVertsBuffer[i1];
                    const p2 = worldVertsBuffer[i2];
                    const p3 = worldVertsBuffer[i3];
                    if (p1.z < -FL+10 || p2.z < -FL+10 || p3.z < -FL+10) return;

                    ctx.moveTo(p1.px, p1.py);
                    ctx.lineTo(p2.px, p2.py);
                    ctx.lineTo(p3.px, p3.py);
                    ctx.lineTo(p1.px, p1.py);
                };

                ctx.beginPath();
                addTri(0, 1, 3);
                addTri(1, 2, 5);
                addTri(3, 4, 6);
                addTri(4, 5, 8);
                ctx.fillStyle = baseFill;
                ctx.fill();
                ctx.stroke();

                ctx.beginPath();
                addTri(1, 4, 3);
                addTri(1, 4, 5);
                addTri(4, 7, 6);
                addTri(4, 7, 8);
                ctx.fillStyle = accentFill;
                ctx.fill();
                ctx.stroke();

                const p1 = worldVertsBuffer[1]; const p4 = worldVertsBuffer[4]; const p7 = worldVertsBuffer[7];
                if(p1.z > -FL) {
                    ctx.beginPath();
                    ctx.strokeStyle = phase === 1 ? '#f59e0b' : '#69B7B2';
                    ctx.lineWidth = 2;
                    ctx.moveTo(p1.px, p1.py); ctx.lineTo(p4.px, p4.py); ctx.lineTo(p7.px, p7.py); 
                    ctx.stroke();
                }
            }

            for(let i=0; i<MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) continue;

                p.x += p.vx; p.y += p.vy; p.z += p.vz;
                p.life -= 0.02;

                if (p.life <= 0 || p.z > 2000) {
                    p.active = false;
                    continue;
                }

                let y1 = p.y * cosY - p.z * sinY;
                let z1 = p.z * cosY + p.y * sinY;
                let x1 = p.x * cosX - z1 * sinX;
                let z2 = z1 * cosX + p.x * sinX;

                const scale = FL / (FL + z2);
                if (scale > 0) {
                    const px = cx + x1 * scale;
                    const py = cy + y1 * scale;

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life * (phase === 2 ? meshOpacity : 1);

                    if (p.type === 'data') {
                        ctx.font = '10px monospace';
                        ctx.fillText("1", px, py);
                    } else {
                        const size = (p.type === 'trail' ? 3 : 6) * scale;
                        ctx.fillRect(px - size/2, py - size/2, size, size);
                    }
                }
            }
            ctx.globalAlpha = 1;
        };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
            mouseY = ((e.clientY - rect.top) / rect.height) * 2 - 1;
        };

        const handleResize = () => {
            if (containerRef.current && canvasRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                canvasRef.current.width = rect.width;
                canvasRef.current.height = rect.height;
                width = rect.width;
                height = rect.height;
                cx = width / 2;
                cy = height / 2;
            }
        };

        const observer = new IntersectionObserver(([entry]) => {
            isVisible = entry.isIntersecting;
        }, { threshold: 0.01 });

        if (containerRef.current) observer.observe(containerRef.current);

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            if (containerRef.current) observer.unobserve(containerRef.current);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return (
        <div ref={containerRef} className="absolute inset-0 w-full h-full bg-[#020202]">
            <canvas ref={canvasRef} className="block w-full h-full" />
        </div>
    );
};

export const ContactHeroVisualizer = React.memo(ContactHeroVisualizerComponent);

import React, { useEffect, useRef } from 'react';

const ContactHeroVisualizerComponent: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = canvas.width;
        let height = canvas.height;
        let cx = width / 2;
        let cy = height / 2;

        let frameId: number;
        let isVisible = true;

        // --- 3D ENGINE SETTINGS ---
        const FL = 800;
        let mouseX = 0;
        let mouseY = 0;
        let targetRotX = 0;
        let targetRotY = 0;

        // --- ANIMATION STATE ---
        let phase = 0; 
        let phaseTimer = 0;
        let globalTime = 0;
        let loopSeed = 0; 
        let meshOpacity = 1; // Start visible

        // --- GEOMETRY DATA STRUCTURES ---
        const SHEET_SIZE = 150; 

        const createVec = (x: number, y: number, z: number) => ({ x, y, z });

        const flatVerts = [
            createVec(-SHEET_SIZE, -SHEET_SIZE * 1.4, 0), createVec(0, -SHEET_SIZE * 1.4, 0), createVec(SHEET_SIZE, -SHEET_SIZE * 1.4, 0),
            createVec(-SHEET_SIZE, 0, 0),                 createVec(0, 0, 0),                 createVec(SHEET_SIZE, 0, 0),
            createVec(-SHEET_SIZE, SHEET_SIZE * 1.4, 0),  createVec(0, SHEET_SIZE * 1.4, 0),  createVec(SHEET_SIZE, SHEET_SIZE * 1.4, 0)
        ];

        const planeVerts = [
            createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),   createVec(0, -SHEET_SIZE * 1.8, -20),
            createVec(-SHEET_SIZE * 1.2, SHEET_SIZE, 20), createVec(0, -SHEET_SIZE * 0.5, -50), createVec(SHEET_SIZE * 1.2, SHEET_SIZE, 20),
            createVec(-20, SHEET_SIZE * 1.4, 0),     createVec(0, SHEET_SIZE * 1.4, 0),      createVec(20, SHEET_SIZE * 1.4, 0)
        ];

        // START AS PLANE (Reverse of original)
        const currentVerts = planeVerts.map(v => ({...v}));
        const worldVertsBuffer = flatVerts.map(() => ({ x: 0, y: 0, z: 0, px: 0, py: 0, scale: 0 }));

        // Start far away for fly-in
        const planePos = { x: 0, y: 0, z: 2500 };
        const planeVel = { x: 0, y: 0, z: -15 }; // Flying backwards towards camera
        const planeRot = { x: 0, y: 0, z: 0 };

        // --- PARTICLES ---
        const MAX_PARTICLES = 60;
        const particles = Array.from({ length: MAX_PARTICLES }, () => ({
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            life: 0,
            color: '#fff',
            type: 'ember' as 'data' | 'trail' | 'ember',
            active: false
        }));

        const lerp = (start: number, end: number, t: number) => start + (end - start) * t;

        const spawnParticle = (type: 'data' | 'trail' | 'ember', ox: number, oy: number, oz: number, spread: number) => {
            for (let i = 0; i < MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) {
                    p.active = true;
                    p.x = ox + (Math.random() - 0.5) * spread;
                    p.y = oy + (Math.random() - 0.5) * spread;
                    p.z = oz + (Math.random() - 0.5) * spread;
                    p.vx = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vy = (Math.random() - 0.5) * (type === 'ember' ? 5 : 2);
                    p.vz = type === 'trail' ? 10 : (Math.random() - 0.5) * 5;
                    p.life = 1.0;
                    // Yellow/Amber Scheme
                    p.color = type === 'data' ? '#FACC15' : type === 'ember' ? '#fbbf24' : '#ffffff';
                    p.type = type;
                    break; 
                }
            }
        };

        const render = () => {
            frameId = requestAnimationFrame(render);
            if (!isVisible) return;

            globalTime += 0.016;

            ctx.fillStyle = 'rgba(2, 2, 2, 0.25)';
            ctx.fillRect(0, 0, width, height);

            targetRotY += (mouseX * 0.1 - targetRotY) * 0.05;
            targetRotX += (mouseY * 0.1 - targetRotX) * 0.05;

            const cosY = Math.cos(targetRotX);
            const sinY = Math.sin(targetRotX);
            const cosX = Math.cos(targetRotY); 
            const sinX = Math.sin(targetRotY);

            // --- PHASE LOGIC (REVERSED) ---

            // PHASE 0: FLIGHT IN (Backwards)
            if (phase === 0) { 
                phaseTimer += 0.01;

                // Move Closer
                planePos.z += planeVel.z;

                // Gentle flight wobble
                planeRot.z = Math.sin(globalTime) * 0.1;
                planeRot.y = Math.cos(globalTime * 0.5) * 0.1;

                // Opacity based on distance
                meshOpacity = Math.min(1, (3000 - planePos.z) / 1000);

                if(Math.random() > 0.5) spawnParticle('ember', planePos.x, planePos.y, planePos.z, 50);

                // Stop when close enough
                if (planePos.z <= 0) {
                    planePos.z = 0;
                    phase = 1;
                    phaseTimer = 0;
                }
            }
            // PHASE 1: UNFOLD (Plane -> Flat)
            else if (phase === 1) { 
                phaseTimer += 0.015;
                const t = Math.min(1, phaseTimer);
                // Elastic ease out
                const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

                for(let i=0; i<9; i++) {
                    // Interpolate Plane -> Flat
                    currentVerts[i].x = lerp(planeVerts[i].x, flatVerts[i].x, ease);
                    currentVerts[i].y = lerp(planeVerts[i].y, flatVerts[i].y, ease);
                    currentVerts[i].z = lerp(planeVerts[i].z, flatVerts[i].z, ease);
                }

                // Reset rotation to flat
                planeRot.x *= 0.95;
                planeRot.y *= 0.95;
                planeRot.z *= 0.95;

                if (t >= 1) {
                    phase = 2;
                    phaseTimer = 0;
                }
            }
            // PHASE 2: DISSOLVE / UNWRITE (Flat -> Chaos)
            else if (phase === 2) { 
                phaseTimer += 0.01;
                meshOpacity = Math.max(0, 1 - phaseTimer); // Fade out

                // Disintegrate geometry
                for(let i=0; i<9; i++) {
                    const noiseX = (Math.random() - 0.5) * 10 * phaseTimer;
                    const noiseY = (Math.random() - 0.5) * 10 * phaseTimer;
                    currentVerts[i].x += noiseX;
                    currentVerts[i].y += noiseY;
                    currentVerts[i].z += (Math.random()) * 5; // Float up
                }

                if (Math.random() > 0.8) spawnParticle('data', 0, 0, 0, 200 * phaseTimer);

                if (phaseTimer > 1.5) { 
                    phase = 3; 
                    phaseTimer = 0; 
                }
            }
            // PHASE 3: RESET (Loop)
            else if (phase === 3) {
                loopSeed += 13.7;
                meshOpacity = 0;

                // Reset to far away plane
                planePos.x = 0; planePos.y = 0; planePos.z = 2500;
                planeRot.x = 0; planeRot.y = 0; planeRot.z = 0;

                // Reset geometry to plane
                for(let i=0; i<9; i++) {
                    currentVerts[i].x = planeVerts[i].x;
                    currentVerts[i].y = planeVerts[i].y;
                    currentVerts[i].z = planeVerts[i].z;
                }

                phase = 0;
            }

            // --- TRANSFORM & PROJECT ---
            for(let i=0; i<9; i++) {
                const v = currentVerts[i];

                // 1. Model Rotation (Plane banking)
                let x = v.x; let y = v.y; let z = v.z;

                const cosRY = Math.cos(planeRot.y); const sinRY = Math.sin(planeRot.y);
                const cosRX = Math.cos(planeRot.x); const sinRX = Math.sin(planeRot.x);
                const cosRZ = Math.cos(planeRot.z); const sinRZ = Math.sin(planeRot.z);

                // Z rot
                let x1 = x * cosRZ - y * sinRZ;
                let y1 = x * sinRZ + y * cosRZ;
                x = x1; y = y1;

                // Y rot
                let x2 = x * cosRY - z * sinRY;
                let z2 = z * cosRY + x * sinRY;
                x = x2; z = z2;

                // X rot
                let y2 = y * cosRX - z * sinRX;
                let z3 = z * cosRX + y * sinRX;
                y = y2; z = z3;

                // 2. World Translation
                x += planePos.x;
                y += planePos.y;
                z += planePos.z;

                // 3. Camera Rotation
                let y3 = y * cosY - z * sinY;
                let z4 = z * cosY + y * sinY;
                let x3 = x * cosX - z4 * sinX;
                let z5 = z4 * cosX + x * sinX;

                const scale = FL / (FL + z5);
                const buff = worldVertsBuffer[i];
                buff.x = x3; buff.y = y3; buff.z = z5;
                buff.px = cx + x3 * scale;
                buff.py = cy + y3 * scale;
                buff.scale = scale;
            }

            if (meshOpacity > 0.01) {
                // Yellow Color Scheme
                const accentFill = `rgba(250, 204, 21, ${meshOpacity * 0.25})`; // Yellow-400
                const baseFill = `rgba(255, 255, 255, ${meshOpacity * 0.05})`;

                ctx.lineWidth = 1;
                ctx.strokeStyle = `rgba(250, 204, 21, ${0.4 * meshOpacity})`; // Yellow Stroke

                const addTri = (i1: number, i2: number, i3: number) => {
                    const p1 = worldVertsBuffer[i1];
                    const p2 = worldVertsBuffer[i2];
                    const p3 = worldVertsBuffer[i3];
                    if (p1.z < -FL+10 || p2.z < -FL+10 || p3.z < -FL+10) return;

                    ctx.moveTo(p1.px, p1.py);
                    ctx.lineTo(p2.px, p2.py);
                    ctx.lineTo(p3.px, p3.py);
                    ctx.lineTo(p1.px, p1.py);
                };

                ctx.beginPath();
                addTri(0, 1, 3);
                addTri(1, 2, 5);
                addTri(3, 4, 6);
                addTri(4, 5, 8);
                ctx.fillStyle = baseFill;
                ctx.fill();
                ctx.stroke();

                ctx.beginPath();
                addTri(1, 4, 3);
                addTri(1, 4, 5);
                addTri(4, 7, 6);
                addTri(4, 7, 8);
                ctx.fillStyle = accentFill;
                ctx.fill();
                ctx.stroke();

                // Highlight Center Line
                const p1 = worldVertsBuffer[1]; const p4 = worldVertsBuffer[4]; const p7 = worldVertsBuffer[7];
                if(p1.z > -FL) {
                    ctx.beginPath();
                    ctx.strokeStyle = '#FBBF24'; // Amber-400
                    ctx.lineWidth = 2;
                    ctx.moveTo(p1.px, p1.py); ctx.lineTo(p4.px, p4.py); ctx.lineTo(p7.px, p7.py); 
                    ctx.stroke();
                }
            }

            // Particles
            for(let i=0; i<MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) continue;

                p.x += p.vx; p.y += p.vy; p.z += p.vz;
                p.life -= 0.02;

                if (p.life <= 0 || p.z > 3000) {
                    p.active = false;
                    continue;
                }

                let y1 = p.y * cosY - p.z * sinY;
                let z1 = p.z * cosY + p.y * sinY;
                let x1 = p.x * cosX - z1 * sinX;
                let z2 = z1 * cosX + p.x * sinX;

                const scale = FL / (FL + z2);
                if (scale > 0) {
                    const px = cx + x1 * scale;
                    const py = cy + y1 * scale;

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life * meshOpacity;

                    if (p.type === 'data') {
                        ctx.font = '10px monospace';
                        ctx.fillText("1", px, py);
                    } else {
                        const size = (p.type === 'trail' ? 3 : 6) * scale;
                        ctx.fillRect(px - size/2, py - size/2, size, size);
                    }
                }
            }
            ctx.globalAlpha = 1;
        };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
            mouseY = ((e.clientY - rect.top) / rect.height) * 2 - 1;
        };

        const handleResize = () => {
            if (containerRef.current && canvasRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                canvasRef.current.width = rect.width;
                canvasRef.current.height = rect.height;
                width = rect.width;
                height = rect.height;
                cx = width / 2;
                cy = height / 2;
            }
        };

        const observer = new IntersectionObserver(([entry]) => {
            isVisible = entry.isIntersecting;
        }, { threshold: 0.01 });

        if (containerRef.current) observer.observe(containerRef.current);

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            if (containerRef.current) observer.unobserve(containerRef.current);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return (
        <div ref={containerRef} className="absolute inset-0 w-full h-full bg-[#020202]">
            <canvas ref={canvasRef} className="block w-full h-full" />
        </div>
    );
};

