        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let time = 0;
        let width = 0;
        let height = 0;

        // --- STATE STORAGE ---
        // We use a mutable object to hold particle state so it persists across frames
        const state: any = {
            particles: [],
            grid: []
        };

        // --- INITIALIZERS ---
        const initSearch = () => {
            state.particles = [];
            for(let i=0; i<50; i++) {
                state.particles.push({
                    theta: Math.random() * Math.PI * 2,
                    phi: Math.random() * Math.PI,
                    r: 80 + Math.random() * 60, // Radius
                    speed: (Math.random() - 0.5) * 0.02
                });
            }
        };

        const initRedaction = () => {
            state.particles = [];
            const cols = 8;
            const rows = 12;
            const cellW = width / cols;
            const cellH = height / rows;
            for(let y=0; y<rows; y++) {
                for(let x=0; x<cols; x++) {
                    if(Math.random() > 0.3) {
                        state.particles.push({
                            x: x * cellW + 5,
                            y: y * cellH + 5,
                            w: cellW - 10,
                            h: cellH - 10,
                            active: false
                        });
                    }
                }
            }
        };

        const initLogic = () => {
            state.grid = [
                { x: width * 0.2, y: height * 0.2 },
                { x: width * 0.8, y: height * 0.2 },
                { x: width * 0.5, y: height * 0.5 },
                { x: width * 0.2, y: height * 0.8 },
                { x: width * 0.8, y: height * 0.8 }
            ];
            state.particles = [];
            for(let i=0; i<10; i++) {
                state.particles.push({
                    from: Math.floor(Math.random() * state.grid.length),
                    to: Math.floor(Math.random() * state.grid.length),
                    progress: Math.random(),
                    speed: 0.02 + Math.random() * 0.03
                });
            }
        };

        const initSwarm = () => {
            state.particles = [];
            for(let i=0; i<40; i++) {
                state.particles.push({
                    x: Math.random() * width,
                    y: Math.random() * height,
                    vx: (Math.random()-0.5) * 2,
                    vy: (Math.random()-0.5) * 2
                });
            }
        };

        const initTranslation = () => {
            state.particles = [];
            const cols = Math.floor(width / 15);
            for(let i=0; i<cols; i++) {
                state.particles.push({
                    x: i * 15,
                    y: Math.random() * height,
                    speed: 1 + Math.random() * 2,
                    char: String.fromCharCode(0x30A0 + Math.random() * 96),
                    updateRate: Math.floor(Math.random() * 10) + 5
                });
            }
        };

        const initShield = () => {
            state.particles = [];
            // Hexagon rings
            for(let r=30; r<120; r+=20) {
                const count = Math.floor((r * Math.PI * 2) / 20);
                for(let i=0; i<count; i++) {
                    state.particles.push({
                        angle: (Math.PI * 2 / count) * i,
                        radius: r,
                        active: 0
                    });
                }
            }
        };

        const initCore = () => {
            state.particles = []; // Just uses time
        };

        const initIdentity = () => {
            state.particles = [];
            for(let i=0; i<100; i++) {
                state.particles.push({
                    angle: Math.random() * Math.PI * 2,
                    r: 40 + Math.random() * 80,
                    speed: (Math.random() - 0.5) * 0.05
                });
            }
        };

        // --- MAIN INIT ROUTER ---
        const initialize = () => {
            if (width === 0 || height === 0) return;

            if (mode === 'search') initSearch();
            else if (mode === 'redaction') initRedaction();
            else if (mode === 'logic') initLogic();
            else if (mode === 'swarm') initSwarm();
            else if (mode === 'translation') initTranslation();
            else if (mode === 'shield') initShield();
            else if (mode === 'core') initCore();
            else initIdentity(); // Identity & default
        };

        // --- RENDERERS ---
        const render = () => {
            time += 0.016;
            ctx.clearRect(0, 0, width, height);

            // Subtle background tint
            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.fillRect(0,0,width,height);

            const cx = width / 2;
            const cy = height / 2;

            if (mode === 'search') {
                ctx.translate(cx, cy);
                state.particles.forEach((p: any) => {
                    p.theta += p.speed;
                    // Project 3D point
                    const x = p.r * Math.sin(p.phi) * Math.cos(p.theta);
                    const y = p.r * Math.sin(p.phi) * Math.sin(p.theta);
                    const z = p.r * Math.cos(p.phi);

                    const scale = 300 / (300 + z);
                    const alpha = (z + 100) / 200; // Depth fade

                    if (scale > 0) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = Math.max(0.1, alpha);
                        ctx.beginPath();
                        ctx.arc(x * scale, y * scale, 2 * scale, 0, Math.PI*2);
                        ctx.fill();

                        // Connecting lines
                        if (Math.random() > 0.99) {
                            ctx.strokeStyle = color;
                            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(x*scale, y*scale); ctx.stroke();
                        }
                    }
                });
                ctx.translate(-cx, -cy);
            }

            else if (mode === 'redaction') {
                const scanLine = (Math.sin(time) * 0.5 + 0.5) * height;
                state.particles.forEach((p: any) => {
                    // Check if scanline passed
                    if (Math.abs(p.y - scanLine) < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 0.8;
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.1)';
                        ctx.globalAlpha = 0.3;
                    }
                    ctx.fillRect(p.x, p.y, p.w, p.h);
                });
                // Draw Scanline
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = 0.5;
                ctx.fillRect(0, scanLine, width, 2);
            }

            else if (mode === 'logic') {
                // Draw Nodes
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                state.grid.forEach((n: any) => {
                    ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                });

                // Draw Paths
                ctx.strokeStyle = 'rgba(255,255,255,0.05)';
                ctx.beginPath();
                state.grid.forEach((n1: any, i: number) => {
                    state.grid.forEach((n2: any, j: number) => {
                        if (i < j) { ctx.moveTo(n1.x, n1.y); ctx.lineTo(n2.x, n2.y); }
                    });
                });
                ctx.stroke();

                // Draw Packets
                state.particles.forEach((p: any) => {
                    p.progress += p.speed;
                    if (p.progress >= 1) {
                        p.progress = 0;
                        p.from = Math.floor(Math.random() * state.grid.length);
                        p.to = Math.floor(Math.random() * state.grid.length);
                    }
                    const n1 = state.grid[p.from];
                    const n2 = state.grid[p.to];
                    const x = n1.x + (n2.x - n1.x) * p.progress;
                    const y = n1.y + (n2.y - n1.y) * p.progress;

                    ctx.fillStyle = color;
                    ctx.shadowColor = color;
                    ctx.shadowBlur = 10;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });
            }

            else if (mode === 'swarm') {
                state.particles.forEach((p: any) => {
                    // Pull to center
                    const dx = cx - p.x;
                    const dy = cy - p.y;
                    p.vx += dx * 0.001;
                    p.vy += dy * 0.001;

                    // Add Noise
                    p.vx += (Math.random()-0.5) * 0.2;
                    p.vy += (Math.random()-0.5) * 0.2;

                    // Friction
                    p.vx *= 0.96;
                    p.vy *= 0.96;

                    p.x += p.vx;
                    p.y += p.vy;

                    ctx.fillStyle = color;
                    ctx.fillRect(p.x, p.y, 2, 2);
                });

                // Connect neighbors
                ctx.strokeStyle = color;
                ctx.globalAlpha = 0.15;
                ctx.beginPath();
                for(let i=0; i<state.particles.length; i++) {
                    for(let j=i+1; j<state.particles.length; j++) {
                        const p1 = state.particles[i];
                        const p2 = state.particles[j];
                        const d = Math.abs(p1.x - p2.x) + Math.abs(p1.y - p2.y);
                        if (d < 40) {
                            ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y);
                        }
                    }
                }
                ctx.stroke();
            }

            else if (mode === 'translation') {
                ctx.font = '12px monospace';
                state.particles.forEach((p: any) => {
                    p.y += p.speed;
                    if (p.y > height) p.y = 0;

                    if (Math.floor(time * 60) % p.updateRate === 0) {
                        p.char = String.fromCharCode(0x30A0 + Math.random() * 96);
                    }

                    const distToCenter = Math.abs(p.x - cx);
                    const alpha = Math.max(0.1, 1 - distToCenter / (width/2));

                    if (p.x < cx) {
                        ctx.fillStyle = 'rgba(255,255,255,0.2)';
                        ctx.fillText(p.char, p.x, p.y);
                    } else {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = alpha;
                        ctx.fillRect(p.x, p.y, 8, 8);
                    }
                });
                // Divider
                ctx.strokeStyle = color;
                ctx.globalAlpha = 0.5;
                ctx.beginPath(); ctx.moveTo(cx, 0); ctx.lineTo(cx, height); ctx.stroke();
            }

            else if (mode === 'shield') {
                ctx.translate(cx, cy);
                state.particles.forEach((p: any) => {
                    if (Math.random() > 0.99) p.active = 1;
                    p.active *= 0.95;

                    const x = Math.cos(p.angle) * p.radius;
                    const y = Math.sin(p.angle) * p.radius;

                    ctx.save();
                    ctx.translate(x, y);
                    ctx.rotate(p.angle); // Align hexagon

                    ctx.strokeStyle = color;
                    ctx.globalAlpha = 0.1 + p.active;
                    ctx.beginPath();
                    for(let i=0; i<6; i++) {
                        const a = i * Math.PI / 3;
                        const hx = Math.cos(a) * 8;
                        const hy = Math.sin(a) * 8;
                        if(i===0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
                    }
                    ctx.closePath();
                    ctx.stroke();
                    if(p.active > 0.5) {
                        ctx.fillStyle = color;
                        ctx.fill();
                    }

                    ctx.restore();
                });
                ctx.translate(-cx, -cy);
            }

            else if (mode === 'core') {
                ctx.translate(cx, cy);

                for(let i=0; i<3; i++) {
                    const r = 40 + i * 25;
                    const angle = time * (i % 2 === 0 ? 1 : -1) * (1 + i * 0.2);

                    ctx.rotate(angle);

                    ctx.strokeStyle = color;
                    ctx.lineWidth = 2;
                    ctx.shadowBlur = 15; ctx.shadowColor = color;

                    ctx.beginPath();
                    ctx.arc(0, 0, r, 0, Math.PI * 1.5);
                    ctx.stroke();

                    ctx.shadowBlur = 0;
                    ctx.rotate(-angle); // Reset rotation for next ring
                }

                // Central Pulse
                const pulse = 10 + Math.sin(time * 5) * 5;
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(0,0, pulse, 0, Math.PI*2); ctx.fill();

                ctx.translate(-cx, -cy);
            }

            else if (mode === 'identity' || mode === 'predictive') {
                ctx.translate(cx, cy);
                ctx.rotate(time * 0.2);

                state.particles.forEach((p: any) => {
                    p.angle += p.speed;
                    const x = Math.cos(p.angle) * p.r;
                    const y = Math.sin(p.angle) * p.r;

                    ctx.fillStyle = color;
                    ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();

                    // Connect to center if close
                    if (Math.random() > 0.98) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                        ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(0,0); ctx.stroke();
                    }
                });
                ctx.translate(-cx, -cy);
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (container.clientWidth > 0 && container.clientHeight > 0) {
                width = container.clientWidth;
                height = container.clientHeight;
                canvas.width = width;
                canvas.height = height;
                initialize();
            }
        };

        // Resize Observer
        const observer = new ResizeObserver(handleResize);
        observer.observe(container);

        handleResize(); // First run
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative bg-black/20">
            <canvas ref={canvasRef} className="block" style={{ width: '100%', height: '100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: string;
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let animationFrameId: number;
        let time = 0;

        // Force resize handling in the render loop to guarantee it catches layout changes
        const render = () => {
            if (!canvas.parentElement) return;

            // Sync canvas buffer size with display size
            // This resets the context state, so we must set styles every frame
            const rect = canvas.parentElement.getBoundingClientRect();
            if (canvas.width !== rect.width || canvas.height !== rect.height) {
                canvas.width = rect.width;
                canvas.height = rect.height;
            }

            const w = canvas.width;
            const h = canvas.height;
            const cx = w / 2;
            const cy = h / 2;

            time += 0.05;

            // 1. Fade Background (Trails)
            ctx.fillStyle = 'rgba(12, 12, 14, 0.2)';
            ctx.fillRect(0, 0, w, h);

            // 2. Draw Center Pulse
            const pulseSize = 20 + Math.sin(time * 2) * 5;
            ctx.shadowBlur = 20;
            ctx.shadowColor = color;
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.arc(cx, cy, pulseSize, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;

            // 3. Draw Orbiting Ring
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(cx, cy, 60, time, time + Math.PI);
            ctx.stroke();

            // 4. Draw Waveform
            ctx.beginPath();
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1;
            for (let x = 0; x < w; x += 5) {
                const y = cy + Math.sin(x * 0.02 + time * 3) * 30 * Math.sin(time);
                if (x === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.stroke();

            // 5. Debug Text (To confirm Props)
            ctx.fillStyle = '#fff';
            ctx.font = '10px monospace';
            ctx.textAlign = 'center';
            ctx.fillText(`MODE: ${mode.toUpperCase()}`, cx, h - 20);

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        return () => cancelAnimationFrame(animationFrameId);
    }, [mode, color]);

    return (
        <div className="w-full h-full relative bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block w-full h-full" />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        // We maintain state in a mutable object to persist across frames without React re-renders
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            grid: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            // Scaling for high DPI displays
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            // CSS size
            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            // Normalize coordinate system
            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            // Re-init if dimensions changed significantly or first run
            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.grid = [];
            state.initializedMode = mode;

            if (mode === 'search') {
                for(let i=0; i<40; i++) {
                    state.particles.push({
                        theta: Math.random() * Math.PI * 2,
                        phi: Math.acos((Math.random() * 2) - 1),
                        radius: 60 + Math.random() * 40,
                        speed: (Math.random() - 0.5) * 0.02
                    });
                }
            }
            else if (mode === 'redaction') {
                const cols = 8;
                const rows = 12;
                const cw = w / cols;
                const ch = h / rows;
                for(let r=0; r<rows; r++) {
                    for(let c=0; c<cols; c++) {
                        if (Math.random() > 0.4) {
                            state.particles.push({
                                x: c * cw + 5, y: r * ch + 5,
                                w: cw - 10, h: ch - 10,
                                active: false
                            });
                        }
                    }
                }
            }
            else if (mode === 'logic') {
                state.nodes = [
                    {x: w*0.2, y: h*0.2}, {x: w*0.8, y: h*0.2},
                    {x: w*0.5, y: h*0.5},
                    {x: w*0.2, y: h*0.8}, {x: w*0.8, y: h*0.8}
                ];
                for(let i=0; i<8; i++) {
                    state.particles.push({
                        from: Math.floor(Math.random()*5),
                        to: Math.floor(Math.random()*5),
                        prog: Math.random(),
                        speed: 0.01 + Math.random() * 0.02
                    });
                }
            }
            else if (mode === 'swarm') {
                for(let i=0; i<30; i++) {
                    state.particles.push({
                        x: w/2, y: h/2,
                        vx: (Math.random()-0.5)*2,
                        vy: (Math.random()-0.5)*2
                    });
                }
            }
            else if (mode === 'translation') {
                const cols = Math.floor(w / 16);
                for(let i=0; i<cols; i++) {
                    state.particles.push({
                        x: i * 16,
                        y: Math.random() * h,
                        speed: 1 + Math.random() * 2,
                        char: String.fromCharCode(0x30A0 + Math.random() * 96)
                    });
                }
            }
            else if (mode === 'identity') {
                for(let i=0; i<60; i++) {
                    state.particles.push({
                        angle: Math.random() * Math.PI * 2,
                        r: 30 + Math.random() * 80,
                        speed: (Math.random() - 0.5) * 0.03
                    });
                }
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            // Draw Mode Specifics
            if (mode === 'search') {
                ctx.translate(cx, cy);
                state.particles.forEach((p: any) => {
                    p.theta += p.speed;
                    const x = p.radius * Math.sin(p.phi) * Math.cos(p.theta);
                    const y = p.radius * Math.sin(p.phi) * Math.sin(p.theta);
                    const z = p.radius * Math.cos(p.phi);
                    const scale = 200 / (200 + z);

                    if (scale > 0) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 0.6 * scale;
                        ctx.beginPath();
                        ctx.arc(x*scale, y*scale, 2*scale, 0, Math.PI*2);
                        ctx.fill();
                    }
                });
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Nodes
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                state.nodes.forEach((n: any) => {
                    ctx.beginPath(); ctx.arc(n.x, n.y, 4, 0, Math.PI*2); ctx.fill();
                });
                // Packets
                state.particles.forEach((p: any) => {
                    p.prog += p.speed;
                    if (p.prog >= 1) {
                        p.prog = 0;
                        p.from = Math.floor(Math.random() * state.nodes.length);
                        p.to = Math.floor(Math.random() * state.nodes.length);
                    }
                    const n1 = state.nodes[p.from];
                    const n2 = state.nodes[p.to];
                    const x = n1.x + (n2.x - n1.x) * p.prog;
                    const y = n1.y + (n2.y - n1.y) * p.prog;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 5; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });
            }
            else if (mode === 'core') {
                ctx.translate(cx, cy);
                for(let i=0; i<3; i++) {
                    ctx.rotate(time * (i%2==0?1:-1) * (1+i*0.5));
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.arc(0,0, 40 + i*30, 0, Math.PI*1.5); ctx.stroke();
                    ctx.rotate(-time * (i%2==0?1:-1) * (1+i*0.5));
                }
                ctx.fillStyle = color;
                ctx.shadowBlur = 20; ctx.shadowColor = color;
                ctx.beginPath(); ctx.arc(0,0, 15 + Math.sin(time*5)*5, 0, Math.PI*2); ctx.fill();
                ctx.shadowBlur = 0;
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'swarm') {
                state.particles.forEach((p: any) => {
                    // Center gravity
                    p.vx += (cx - p.x) * 0.001;
                    p.vy += (cy - p.y) * 0.001;
                    p.x += p.vx;
                    p.y += p.vy;

                    ctx.fillStyle = color;
                    ctx.fillRect(p.x, p.y, 2, 2);
                });

                // Lines
                ctx.strokeStyle = color;
                ctx.globalAlpha = 0.2;
                ctx.beginPath();
                for(let i=0; i<state.particles.length; i++) {
                    for(let j=i+1; j<state.particles.length; j++) {
                        const p1 = state.particles[i];
                        const p2 = state.particles[j];
                        const d = Math.abs(p1.x-p2.x) + Math.abs(p1.y-p2.y);
                        if (d < 50) {
                            ctx.moveTo(p1.x, p1.y);
                            ctx.lineTo(p2.x, p2.y);
                        }
                    }
                }
                ctx.stroke();
            }
            else if (mode === 'translation') {
                ctx.font = '10px monospace';
                state.particles.forEach((p: any) => {
                    p.y += p.speed;
                    if (p.y > h) p.y = 0;

                    const dist = Math.abs(p.x - cx);
                    const alpha = Math.max(0.1, 1 - dist/(w/2));

                    if (p.x < cx) {
                        ctx.fillStyle = 'rgba(255,255,255,0.3)';
                        ctx.fillText(p.char, p.x, p.y);
                    } else {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = alpha;
                        ctx.fillRect(p.x, p.y, 8, 8);
                    }
                });
                ctx.strokeStyle = color;
                ctx.globalAlpha = 0.5;
                ctx.beginPath(); ctx.moveTo(cx, 0); ctx.lineTo(cx, h); ctx.stroke();
            }
            else if (mode === 'identity') {
                ctx.translate(cx, cy);
                ctx.rotate(time * 0.2);
                state.particles.forEach((p: any) => {
                    p.angle += p.speed;
                    const x = Math.cos(p.angle) * p.r;
                    const y = Math.sin(p.angle) * p.r;
                    ctx.fillStyle = color;
                    ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();
                    if (Math.random() > 0.98) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(x,y); ctx.stroke();
                    }
                });
                ctx.translate(-cx, -cy);
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        // Resize Observer to handle layout changes
        const observer = new ResizeObserver(() => {
            resize();
        });
        observer.observe(container);

        // Initial setup
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            {/* Scanline Overlay */}
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

